const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let base, data, view='hotspot', selected='', grade='', market='', query='', pair=['green','shuanghuan'], scenario='ramp', exposure=30,volume=-10,price=0,answer=null,draft=null,updateError='',updateText='',busy=false,online=false,history=[],chatQuestion='',updateMode='form',contextClaim=null,notebook=[],hotTopic='growth',hotQuestion='',hotTab='financials',hotChart='trend',shareCompany='green',hotExpanded='C01',hotAnswer=null,trendRange='all',trendMetrics=['revenue','profit','cash'],trendSelected=null,financialExpanded=null,companyQuery='',companyNode='',companyMarket='',companyDepth='',documentQuery='',documentCompany='',documentKind='',selectedFund='robotcn',watchCompanies=[];
