const titles={data:['iFinD 数据台'],explore:['企业研究'],library:['公告与研报'],funds:['主题基金'],ai:['AI 研究'],hotspot:['人形机器人研究'],chain:['人形机器人研究'],compare:['公司对比'],scenario:['产业变化如何影响公司'],updates:['研究动态'],notebook:['研究动态'],delivery:['资料与说明']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function saveHistory(next){const checked=validateHistory(next,base);localStorage.setItem(HISTORY_FORMAT,JSON.stringify(checked));history=checked;rebuild();}
function rebuild(){data=applyHistory(base,history);}
function activeClaim(id){return data.claims.find(c=>c.id===id)||data.archivedClaims?.find(c=>c.id===id);}
function periodLabel(c){return c.periodStart+' — '+c.periodEnd;}
function reviewMeta(c){return `<div class="fact-dimensions"><span>类别：${esc(c.evidenceCategory||'不适用')}</span><span>阶段：${esc(c.businessStage||'未知')}</span><span>方向：${esc(c.supportDirection||'不能判断')}</span><span>${c.reviewStatus||'待复核'}${c.validity?.conflict?' · 存在冲突':''}${c.validity?.superseded?' · 已被替代':''}</span></div>`;}
function exploreView(){const rows=filterCompanies({q:companyQuery,node:companyNode,market:companyMarket,deep:companyDepth});return `<div class="explore-overview"><div><strong>${CATALOG.length}</strong><span>研究企业</span></div><div><strong>${CATALOG.filter(c=>c.deep).length}</strong><span>财务与证据深度样本</span></div><div><strong>${new Set(CATALOG.map(c=>c.market)).size}</strong><span>市场</span></div><div><strong>${watchCompanies.length}</strong><span>本机关注</span></div></div><div class="explore-toolbar"><input id="company-query" aria-label="查找企业" placeholder="公司、代码或业务" value="${esc(companyQuery)}"><select id="company-node" aria-label="企业产业环节"><option value="">全部产业环节</option>${data.levels.flatMap(l=>l.nodes).map(n=>`<option value="${n.id}" ${companyNode===n.id?'selected':''}>${n.name}</option>`).join('')}</select><select id="company-market" aria-label="企业市场"><option value="">全部市场</option>${[...new Set(CATALOG.map(c=>c.market))].map(x=>`<option ${companyMarket===x?'selected':''}>${x}</option>`).join('')}</select><select id="company-depth" aria-label="核查深度"><option value="">全部核查层级</option><option value="deep" ${companyDepth==='deep'?'selected':''}>财务与证据深度样本</option><option value="profile" ${companyDepth==='profile'?'selected':''}>业务与产品资料</option></select></div>${scatterView(ifind)}<div class="library-count"><span>${rows.length} 家匹配企业</span></div><section class="catalog-table-wrap"><table class="catalog-table"><thead><tr><th>公司 / 市场</th><th>研究环节</th><th>已收录内容</th><th>核查范围</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="company-name" data-company="${c.id}">${esc(c.name)}</button><small>${c.ticker} · ${c.market}</small></td><td>${c.nodes.map(id=>`<span class="catalog-tag">${nodeName(id)}</span>`).join('')}</td><td><span class="${c.deep?'status-deep':'status-profile'}">${c.basis}</span><small>${esc(c.description)}</small></td><td><span>${c.deep?'财务 / 关系证据 / 可比性':'产品能力 / 资料线索'}</span><small>${c.date?'材料日期 '+c.date:'网页未标发布日期 · 核查 '+CHECKED_AT}</small></td><td><button data-company="${c.id}" class="row-toggle">研究 ↗</button><button data-watch-company="${c.id}" class="watch-button ${watchCompanies.includes(c.id)?'active':''}" aria-pressed="${watchCompanies.includes(c.id)}">${watchCompanies.includes(c.id)?'已关注':'＋关注'}</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">暂无匹配企业</div>'}</section>`;}
function nodeName(id){return data.levels.flatMap(l=>l.nodes).find(n=>n.id===id)?.name||id;}
function showCompany(id){const c=companyById(id),claims=data.claims.filter(x=>x.company===id),docs=filterDocuments({company:id});if(!c)return;modal(`<div class="company-profile-head"><div><span class="eyebrow">企业研究</span><h2>${c.name}</h2><p>${c.ticker} · ${c.market}</p></div><span class="badge ${c.deep?'red':'neutral'}">${c.deep?'深度研究样本':'产品与业务线索'}</span></div><div class="profile-nodes">${c.nodes.map(id=>`<span class="catalog-tag">${nodeName(id)}</span>`).join('')}</div>${companyFinancial(ifind,id)}<h3>业务关联</h3><p>${esc(c.description)}</p><a href="${c.source}" target="_blank" rel="noopener noreferrer">${esc(c.sourceTitle)} ↗</a><p class="small">${c.date?'材料日期 '+c.date:'网页未标发布日期'} · 核查 ${CHECKED_AT} · 来源为公司披露</p>${claims.length?`<h3>业务证据</h3>${claims.map(x=>`<div class="profile-evidence"><strong>${esc(x.concept)}</strong>${badge(x.grade)}<p>${esc(x.text)}</p>${claimButton(x,'['+x.id+'] 核对原文')}</div>`).join('')}`:'<div class="profile-gap"><strong>继续核查</strong><p>尚未完成该公司的人形客户身份、订单交付、应用收入拆分和财务期间核验。当前资料不参与人形收入排名或已核实供应商计数。</p></div>'}${docs.length?`<h3>公司公告 · ${docs.length}</h3>${docs.map(d=>`<button class="profile-document" data-document="${d.id}"><span>${d.title}</span><small>${d.date} ↗</small></button>`).join('')}`:'<p class="small">该公司尚未收录法定公告；上方提供官网资料，不代表无相关公告。</p>'}<div class="modal-actions"><button id="profile-materials">关联资料</button><button id="profile-compare">公司对比</button><button id="profile-ai" class="primary">AI 核查业务关联</button></div>`);bindModalLinks();$('#profile-materials').onclick=()=>{$('#modal').close();documentCompany=id;documentKind='';documentQuery='';view='library';render();window.scrollTo(0,0)};$('#profile-compare').onclick=()=>{$('#modal').close();pair=[id,id==='green'?'hds':'green'];view='compare';render();window.scrollTo(0,0)};$('#profile-ai').onclick=()=>{$('#modal').close();view='ai';chatQuestion=c.name+'与人形机器人有哪些真实业务关系？';answer=null;render();window.scrollTo(0,0);ask(chatQuestion)};}
function libraryView(){const docs=filterDocuments({q:documentQuery,kind:documentKind,company:documentCompany});return `<div class="library-heading"><span class="badge neutral">公开资料库 · ${DOCUMENTS.length} 份</span></div><div class="library-tabs">${[['','全部资料'],['公告','公司公告'],['研报','行业研报']].map(([id,t])=>`<button data-document-kind="${id}" class="${documentKind===id?'active':''}">${t}<small>${DOCUMENTS.filter(d=>!id||d.kind===id).length}</small></button>`).join('')}</div><div class="explore-toolbar"><input id="document-query" aria-label="搜索公告或研报" placeholder="标题、公司或研究主题" value="${esc(documentQuery)}"><select id="document-company" aria-label="资料关联企业"><option value="">全部关联公司</option>${CATALOG.map(c=>`<option value="${c.id}" ${documentCompany===c.id?'selected':''}>${c.name}</option>`).join('')}</select><span class="toolbar-note">按披露日期排序</span></div><div class="document-list">${docs.map(d=>`<article class="document-row"><div class="document-type">${d.kind}<time>${d.date}</time></div><div><button class="document-title" data-document="${d.id}">${esc(d.title)}</button><p>${esc(d.summary)}</p><div class="document-meta"><span>${esc(d.publisher)}</span><span>${esc(d.scope)}</span></div></div><div class="document-actions"><button data-document="${d.id}">阅读与核查 ↗</button>${d.sample?`<button data-research-sample="${d.sample}" class="ai-text">✧ AI 研究回放</button>`:d.extraction?'<button data-extract-document="'+d.id+'" class="ai-text">✧ AI 公告抽取</button>':'<button data-document="'+d.id+'" class="ai-text">研究假设与边界</button>'}</div></article>`).join('')||'<div class="empty">暂无匹配资料</div>'}</div>${noticeList(ifind,{company:documentCompany,query:documentQuery,kind:documentKind})}<div class="library-boundary">研报为公开摘要；iFinD片段待原文核验。</div>`;}
function showDocument(id,extract=false){const d=DOCUMENTS.find(x=>x.id===id);if(!d)return;const x=d.extraction;modal(`<div class="eyebrow">${d.kind} · ${esc(d.publisher)}</div><h2>${esc(d.title)}</h2><p class="small">${d.date} · ${esc(d.scope)}</p><p>${esc(d.summary)}</p><p><b>原文定位</b><br>${esc(d.locator)}</p><a href="${d.url}" target="_blank" rel="noopener noreferrer">打开作者 / 公司原文 ↗</a>${d.research?`<div class="profile-gap"><strong>研究假设与使用边界</strong><p>${esc(d.research)}</p><p>${d.id==='R_MS25'?'研究时检查售价、采用速度、成本与场景付费，再跟踪公司订单和交付；不能把长期情景当作当年经营事实。':'先区分工业、人形与服务机器人，再检查地区、期间和安装/出货定义；不能将行业需求直接分摊到公司营收。'}</p></div>`:''}${x?`<div class="extraction-panel"><div class="panel-title"><h3>AI 公告抽取</h3><span class="badge yellow">开发阶段Codex结果 · 离线回放</span></div>${extract?`<dl>${[['公司',x.company],['产品',x.product],['证据类别 / 阶段',x.category+' / '+x.stage],['合同金额','未披露'],['交付状态',x.delivery],['收入确认',x.revenue],['交易对手',x.counterparty]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><blockquote class="source-quote">${d.quote}</blockquote><p class="small">原文第1页 · 预付款不等于收入。页面回放已有结构化结果，不发生在线模型调用。</p>`:'<p>从公告中分开识别合同、预付款、交付与收入；保留缺失字段。</p><button data-extract-document="'+d.id+'" class="primary">查看抽取结果</button>'}</div>`:''}<div class="modal-actions">${d.companyIds.map(id=>`<button data-company="${id}">查${companyById(id).name} ↗</button>`).join('')}${d.sample?`<button data-research-sample="${d.sample}" class="primary">AI 研究回放</button>`:''}</div>`);bindModalLinks();}
function fundsView(){const f=FUNDS.find(x=>x.id===selectedFund);return `<div class="fund-options">${FUNDS.map(f=>`<button data-fund="${f.id}" class="${selectedFund===f.id?'active':''}"><span>${f.market}</span><strong>${f.name}</strong><small>${f.ticker}</small></button>`).join('')}</div><div class="fund-scope"><div><span>跟踪标的</span><strong>${esc(f.benchmark)}</strong></div><div><span>主题范围</span><strong>${esc(f.scope)}</strong></div><a href="${f.url}" target="_blank" rel="noopener noreferrer">基金公司资料 ↗</a></div>${fundChart(f.id)}<section class="fund-holdings"><div class="panel-title"><h2>持仓穿透</h2><span>${f.asOf?'历史快照 · '+f.asOf:'持仓数据未导入'}</span></div>${f.holdings.length?`<p class="small">${f.holdingsScope}</p><table class="catalog-table"><thead><tr><th>持仓公司</th><th>占基金资产净值</th><th>研究环节</th><th></th></tr></thead><tbody>${f.holdings.map(h=>`<tr><td><button class="company-name" data-company="${h.company}">${h.name}</button><small>${companyById(h.company).ticker}</small></td><td class="holding-weight">${h.weight.toFixed(2)}%</td><td>${companyById(h.company).nodes.map(id=>nodeName(id)).join(' / ')}</td><td><button data-company="${h.company}">查业务证据 ↗</button></td></tr>`).join('')}</tbody></table><div class="fund-source"><a href="${f.report}#page=9" target="_blank" rel="noopener noreferrer">${f.locator} ↗</a><span>报告期 ${f.period} · 报告送出 ${f.published}</span></div>`:`<div class="empty"><p>${f.holdingsScope}</p><a href="${f.url}" target="_blank" rel="noopener noreferrer">查看基金公司持仓披露 ↗</a></div>`}</section><div class="market-data-boundary"><strong>行情与资金流</strong><span>实时行情与资金流未接入</span></div>`;}
function aiView(){return `<div class="ai-workspace"><div class="ai-intro"><div><span class="ai-symbol">✧</span><h2>从证据到判断</h2></div><span class="badge ${online?'red':'yellow'}">${online?'在线模型已配置 · 输出需复核':'离线回放 / 证据检索'}</span></div><div class="ai-task-grid">${RESEARCH_SAMPLES.map(s=>`<button data-research-sample="${s.id}"><small>✧ AI 研究回放</small><strong>${esc(s.short)}</strong><span>${esc(s.summary)}</span><i>打开结果 ↗</i></button>`).join('')}</div><section class="ai-query"><div class="panel-title"><h2>研究问答</h2><span>${online?'可选在线分析':'本地证据检索'}</span></div><textarea id="question" aria-label="输入公司或概念问题" placeholder="例如：优必选的采购合同能证明已确认收入吗？" maxlength="1000">${esc(chatQuestion)}</textarea><div class="ai-query-actions"><span>检索范围：${CATALOG.length}家企业资料 · ${data.companies.length}家深度证据样本</span>${online?'<label><input type="checkbox" id="use-model">在线 AI 分析公开证据</label>':''}<button class="primary" id="ask" ${busy?'disabled':''}>${busy?'分析中…':online?'开始研究':'检索业务证据'} ↗</button></div>${answer?`<div class="ai-query-answer" aria-live="polite"><span class="badge ${answer.mode==='AI'?'red':'neutral'}">${answer.mode==='AI'?'AI 结果 · 待复核':'本地证据检索'}</span><p>${esc(answer.text)}</p>${(answer.profiles||[]).map(id=>{const c=companyById(id);return `<div class="ai-profile-result"><strong>${c.name} · ${c.basis}</strong><p>${esc(c.description)}</p><a href="${c.source}" target="_blank" rel="noopener noreferrer">${esc(c.sourceTitle)} ↗</a><button data-company="${id}">打开企业研究 ↗</button></div>`}).join('')}${(answer.documents||[]).map(id=>{const d=DOCUMENTS.find(d=>d.id===id);return `<button class="profile-document" data-document="${d.id}"><span>${esc(d.title)}</span><small>${d.date} · 核查 ↗</small></button>`}).join('')}${(answer.ifindCompanies||[]).map(id=>companyFinancial(ifind,id)).join('')}${answer.claims.map(c=>`<div class="profile-evidence"><strong>${esc(companyById(c.company)?.name)} · ${esc(c.concept)}</strong>${badge(c.grade)}<p>${esc(c.text)}</p>${claimButton(c,'['+c.id+'] 核查证据')}</div>`).join('')}${answer.modelText?`<div class="info-box">${esc(answer.modelText)}</div>`:''}</div>`:''}</section><section class="ai-extraction-entry"><div><span>✧ AI 公告抽取 · 离线回放</span><h3>优必选 · 合同要素抽取</h3></div><button data-extract-document="D_UB25">查看结构化结果 ↗</button></section><details class="inline-details"><summary>AI与数据说明</summary><p>AI样例为开发阶段分析回放；问答使用本地证据检索。iFinD读取已导入快照，在线模型与自动采集未启用。</p></details></div>`;}
function profileCompare(){const a=companyById(pair[0]),b=companyById(pair[1]),common=a.nodes.filter(id=>b.nodes.includes(id));return `<div class="compare-select">${[a,b].map((c,i)=>`<label>公司 ${i?'B':'A'}<select id="pair-${i?'b':'a'}" aria-label="${i?'第二':'第一'}家公司">${CATALOG.map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${x.name} · ${x.ticker}</option>`).join('')}</select></label>`).join('<span>⇄</span>')}</div><div class="compare-grid">${[a,b].map(c=>`<section class="card company-card"><small>${c.en}</small><h2>${c.name}</h2><p>${c.ticker} · ${c.market}</p><div class="profile-nodes">${c.nodes.map(id=>`<span class="catalog-tag">${nodeName(id)}</span>`).join('')}</div><p>${esc(c.description)}</p><a href="${c.source}" target="_blank" rel="noopener noreferrer">${esc(c.sourceTitle)} ↗</a><p class="small">${c.date?'材料日期 '+c.date:'网页未标发布日期；核查 '+CHECKED_AT}</p></section>`).join('')}</div><section class="card"><div class="card-head"><h2>可比性与缺口</h2><span class="badge neutral">业务参照 · 财务未对齐</span></div><table class="matrix"><thead><tr><th>维度</th><th>可以研究什么</th><th>横比限制</th></tr></thead><tbody><tr><td>产业位置</td><td>${common.length?'重合研究入口：'+common.map(nodeName).join('、'):'当前没有重合节点，可研究上下游机制'}</td><td>同一节点不等于技术路线、型号、客户或采购关系相同。</td></tr><tr><td>业务证据</td><td>${a.name}：${a.basis}<br>${b.name}：${b.basis}</td><td>产品介绍、研发、合同与财务收入的证据强度分别核验。</td></tr><tr><td>应用范围</td><td>对齐具体产品、应用场景及商业阶段。</td><td>公司工业业务与人形应用不可混用；未核实专属收入。</td></tr><tr><td>财务横比</td><td>待补齐期间、产品范围、合并范围和指标定义。</td><td>尚未完成对齐，不开放收入差额、利润率或估值排名。</td></tr></tbody></table></section>`;}
function bindModalLinks(){const m=$('#modal');m.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>showCompany(b.dataset.company));m.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>showDocument(b.dataset.document));m.querySelectorAll('[data-extract-document]').forEach(b=>b.onclick=()=>showDocument(b.dataset.extractDocument,true));m.querySelectorAll('[data-research-sample]').forEach(b=>b.onclick=()=>showResearchSample(b.dataset.researchSample));m.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>showClaim(b.dataset.claim));bindIfind();}
function exportExplore(){let text='# 链证研究资料\n\n导出 '+new Date().toISOString()+'\n公开资料与iFinD财务、公告快照（分开核验）。\n\n';if(view==='explore')text+=filterCompanies({q:companyQuery,node:companyNode,market:companyMarket,deep:companyDepth}).map(c=>'## '+c.name+' '+c.ticker+'\n'+c.basis+'\n'+c.description+'\n'+c.source+'\n材料日期：'+(c.date||'网页未标注')+'；核查：'+CHECKED_AT).join('\n\n');else if(view==='library')text+=filterDocuments({q:documentQuery,kind:documentKind,company:documentCompany}).map(d=>'## '+d.title+'\n'+d.date+' | '+d.scope+'\n'+d.summary+'\n'+d.locator+'\n'+d.url).join('\n\n');else if(view==='funds'){const f=FUNDS.find(x=>x.id===selectedFund);text+=f.name+' '+f.ticker+'\n'+f.scope+'\n截至：'+(f.asOf||'未获取持仓日期')+'\n'+f.holdingsScope+'\n'+f.holdings.map(h=>h.name+' '+h.weight+'%').join('\n')+'\n'+f.report;}else text+=(answer?answer.text+'\n'+(answer.profiles||[]).map(id=>{const c=companyById(id);return c.name+' '+c.ticker+'\n'+c.description+'\n'+c.source;}).join('\n')+'\n'+(answer.documents||[]).map(id=>{const d=DOCUMENTS.find(d=>d.id===id);return d.title+' '+d.date+'\n'+d.summary+'\n'+d.locator+'\n'+d.url}).join('\n')+'\n'+answer.claims.map(c=>'['+c.id+'] '+c.text+'\n'+data.sources.find(s=>s.id===c.source).url).join('\n'):'暂无问答结果。请先运行证据检索或打开研究回放。');if(view==='ai'&&answer?.ifindCompanies?.length)text+='\n\n'+comparisonExport(ifind,answer.ifindCompanies);download('ChainLens-'+view+'.md',text,'text/markdown');}
function bindExplore(){document.querySelectorAll('[data-explore-node]').forEach(b=>b.onclick=()=>{companyNode=b.dataset.exploreNode;companyQuery=companyMarket=companyDepth='';view='explore';render();window.scrollTo(0,0)});document.querySelectorAll('[data-company]').forEach(b=>b.onclick=()=>showCompany(b.dataset.company));document.querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>showDocument(b.dataset.document));document.querySelectorAll('[data-extract-document]').forEach(b=>b.onclick=()=>showDocument(b.dataset.extractDocument,true));document.querySelectorAll('[data-watch-company]').forEach(b=>b.onclick=()=>{const id=b.dataset.watchCompany,next=watchCompanies.includes(id)?watchCompanies.filter(x=>x!==id):[...watchCompanies,id];try{localStorage.setItem('chainlens-company-watch-v1',JSON.stringify(next));watchCompanies=next;render()}catch{toast('浏览器存储不可用，关注未保存')}});if($('#company-query'))$('#company-query').oninput=e=>{companyQuery=e.target.value;render()};for(const [id,key]of [['company-node','node'],['company-market','market'],['company-depth','depth']])if($('#'+id))$('#'+id).onchange=e=>{if(key==='node')companyNode=e.target.value;if(key==='market')companyMarket=e.target.value;if(key==='depth')companyDepth=e.target.value;render()};if($('#document-query'))$('#document-query').oninput=e=>{documentQuery=e.target.value;render()};if($('#document-company'))$('#document-company').onchange=e=>{documentCompany=e.target.value;render()};document.querySelectorAll('[data-document-kind]').forEach(b=>b.onclick=()=>{documentKind=b.dataset.documentKind;render()});document.querySelectorAll('[data-fund]').forEach(b=>b.onclick=()=>{selectedFund=b.dataset.fund;render()});}

function showRestore(){if(!history.length)return;let points=[{label:'初始基准',ids:[]}];for(let i=0;i<history.length;i++)points.push({label:'操作'+(i+1)+'之后 · '+history[i].type,ids:activeUpdateIds(history.slice(0,i+1))});modal(`<h2>恢复指定版本</h2><p>追加恢复操作，保留全部后续证据、研究与审计历史。</p><div class="journal-form"><label>恢复点<select id="restore-point">${points.map((v,i)=>`<option value="${i}">${v.label}</option>`).join('')}</select></label><label>复核人 / 署名（自填）<input id="restore-reviewer" maxlength="100"></label><label>恢复理由<textarea id="restore-reason" maxlength="1000"></textarea></label></div><p id="restore-error"></p><div class="modal-actions"><button id="restore-confirm" class="primary">确认恢复并留痕</button></div>`);$('#restore-confirm').onclick=()=>{try{const e=restoreEvent(history,{reviewer:$('#restore-reviewer').value,reason:$('#restore-reason').value});e.activeIds=points[Number($('#restore-point').value)].ids;saveHistory([...history,e]);$('#modal').close();render();toast('已追加恢复操作，历史未删除')}catch(e){$('#restore-error').textContent=e.message}};}

function badge(g){return `<span class="badge ${GRADES[g].color}">${g} · ${GRADES[g].label}</span>`}
function srcButton(id,label){return `<button class="link-button" data-source="${esc(id)}">${esc(label||id)} ↗</button>`}
function claimButton(c,label='查看证据'){return `<button class="link-button" data-claim="${esc(c.id)}">${esc(label)} ↗</button>`}
function uiIcon(kind){const paths={hotspot:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5M8 11h6M11 8v6"/>',notebook:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>',chain:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m6 13 3-4 4 7 3-4h3"/>',compare:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',scenario:'<path d="M4 19V5m0 14h17M7 14l4-5 4 3 5-7"/>',updates:'<path d="M20 7v5h-5M4 17v-5h5M6.1 7a7 7 0 0 1 11.7-2L20 8M4 16l2.2 3A7 7 0 0 0 18 17"/>',explore:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-3a7 7 0 0 1 12-5m1 4h7m-3-3v6"/>',library:'<path d="M4 3h12l4 4v14H4zM15 3v5h5M7 12h10M7 16h8"/>',funds:'<path d="M3 20h18M6 16V9m6 7V4m6 12V7"/>',ai:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',delivery:'<path d="M7 3h10l4 4v14H3V3h4m10 0v5h4M7 12l2 2 4-4M7 18h10"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]||paths.chain}</svg>`}
function shell(){return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><div><strong>ChainLens</strong></div></div><nav class="nav" aria-label="主要导航">${[['hotspot','产业链研究'],['explore','查企业'],['library','公告与研报'],['funds','主题基金'],['ai','AI 研究'],['compare','公司对比'],['data','iFinD 数据台'],['scenario','变化影响分析'],['updates','研究动态']].map(([v,t])=>`<button data-view="${v}" class="${(view===v||(v==='hotspot'&&view==='chain')||(v==='updates'&&view==='notebook'))?'active':''}" ${(view===v||(v==='hotspot'&&view==='chain')||(v==='updates'&&view==='notebook'))?'aria-current="page"':''}><span class="ico">${uiIcon(v)}</span>${t}${v==='updates'&&notebook.some(r=>evidenceChanged(r,data))?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav><div class="side-foot"><button data-view="delivery" class="side-resource ${view==='delivery'?'active':''}">${uiIcon('delivery')}资料与说明</button></div></aside><main class="main"><header class="topbar"><form id="global-search-form" class="topbar-search" role="search"><span class="search-orb">${uiIcon('search')}</span><input id="global-search" aria-label="全局搜索公司或概念" placeholder="搜索公司、代码或概念" value="${esc(query)}" autocomplete="off"></form><div class="topright">${providerBadge(ifind)}<button class="top-ai-entry" data-view="ai">✧ AI 研究</button><span class="pill">${online?'在线模型已配置':'AI 离线回放'}</span></div></header><div class="content"><div class="heading"><h1>${titles[view][0]}</h1><button id="export" class="primary" ${view==='notebook'&&!notebook.length?'disabled':''}>${view==='notebook'?'导出台账':'导出研究'} ↗</button></div>${sectionNav()}${view==='data'?mcpView(ifind):view==='explore'?exploreView():view==='library'?libraryView():view==='funds'?fundsView():view==='ai'?aiView():view==='hotspot'?hotspotView():view==='chain'?chainView():view==='compare'?compareView():view==='scenario'?scenarioView():view==='delivery'?deliveryView():view==='notebook'?notebookView():updatesView()}<footer class="footer"><span>历史披露 · 不构成投资建议</span><span>${srcButton('method','研究方法')} ${srcButton('deliverables','资料与说明')}</span></footer></div></main></div>`}

function sectionNav(){const pages=['hotspot','chain'].includes(view)?[['hotspot','热点核查'],['chain','产业链图谱']]:['updates','notebook'].includes(view)?[['updates','待复核材料'],['notebook','研究台账']]:[];return pages.length?`<div class="section-nav">${pages.map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}">${label}${id==='notebook'&&notebook.some(r=>evidenceChanged(r,data))?' · 待复核':''}</button>`).join('')}</div>`:'';}

function selectTopic(id){const t=topicById(id);if(!t)return;hotTopic=id;hotQuestion='';hotTab=id==='growth'?'financials':'companies';hotChart=t.chart==='growth'?'trend':t.chart;shareCompany=t.company;hotExpanded=t.claims[0];hotAnswer=null;render();}
function hotspotView(){
 const t=topicById(hotTopic),claims=topicClaims(t,data),additions=claims.filter(c=>!t.claims.includes(c.id)),tabs=[...(t.id==='growth'?[['financials','季度明细']]:[]),['companies','业务证据'],['chain','产业链'],['transmission','影响路径'],['activity','研究动态']];
 return `<form class="topic-question" id="topic-question-form"><span>${uiIcon('search')}</span><input id="topic-question" aria-label="热点研究问题" value="${esc(hotQuestion||t.question)}" maxlength="1000" autocomplete="off"><button class="primary" type="submit">AI 研究</button></form><div class="topic-switch"><div>${TOPICS.map(x=>`<button data-topic="${x.id}" class="${!hotAnswer&&x.id===t.id?'active':''}">${x.label}</button>`).join('')}</div></div>${hotAnswer?`<section class="research-query-result"><h2>${hotAnswer.refused?'研究边界':'检索结果'}</h2><p>${esc(hotAnswer.text)}</p>${hotAnswer.claims.map(c=>`<div class="query-fact"><strong>${esc(data.companies.find(x=>x.id===c.company)?.name)} · ${esc(c.concept)}</strong>${badge(c.grade)}<p>${esc(c.text)}</p>${claimButton(c,'核对来源')}</div>`).join('')}</section>`:`<div class="research-metrics">${topicMetrics(t,data).map(m=>`<${m.claim?'button':'div'} class="research-metric" ${m.claim?`data-claim="${m.claim}"`:''}><span>${m.label}</span><strong class="${m.value.length>7?'metric-word':''}">${m.value}<small>${m.unit||''}</small></strong><p>${m.note}</p></${m.claim?'button':'div'}>`).join('')}</div>
 <section class="research-chart chart-stage"><div class="panel-title"><div><h2>${hotChart==='trend'?'经营趋势':hotChart==='share'?'业务收入结构':hotChart==='growth'?'产品组年度对照':hotChart==='grade'?'概念证据状态':'影响路径'}</h2>${hotChart==='trend'?'<p class="chart-subtitle">绿的谐波 · 公司合并口径 · 单季度</p>':''}</div><div class="chart-mode">${chartModes(t).map(([id,label])=>`<button data-chart-mode="${id}" class="${hotChart===id?'active':''}">${label}</button>`).join('')}</div></div>${hotChart==='trend'?financialTrend():hotChart==='share'?businessShareChart():hotChart==='growth'?shipmentChart():hotChart==='grade'?evidenceStateChart():topicPathChart(t)}</section>
 <div class="research-takeaway"><span class="takeaway-mark">✧ AI研究判断<small>离线样例</small></span><div><strong>${t.conclusion}</strong></div><button id="save-topic">${notebook.some(r=>r.id===t.sample)?'打开研究':'保存研究'} ↗</button></div>
 <section class="research-workbench"><div class="research-tabs">${tabs.map(([id,label])=>`<button data-research-tab="${id}" class="${hotTab===id?'active':''}">${label}${id==='companies'?` <small>${claims.length}</small>`:''}</button>`).join('')}<span>${hotTab==='financials'?'公司合并口径 · 单季度':additions.length?'含新增证据':'公开披露'}</span></div>${hotTab==='financials'?financialTable():hotTab==='companies'?topicCompanyTable(t,claims):hotTab==='chain'?topicChain(t):hotTab==='transmission'?topicTransmission(t):topicActivity(t,claims)}</section>`}`;
}
function chartModes(t){return t.chart==='share'?[['share','业务结构'],['path','影响路径']]:t.chart==='growth'?[['trend','季度趋势'],['growth','产品组年度']]:t.chart==='grade'?[['grade','证据状态']]:[['path','影响路径']];}
function money(v){return v.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function signed(v,digits=2){return (v>0?'+':'')+v.toFixed(digits);}
function financialTrend(){
 const rows=quartersFor(trendRange),points=lineSegments(rows,'revenue')[0],notable=rows.map(q=>({q,change:quarterChange(q.id)})).filter(x=>x.change&&x.change.percent!=null).sort((a,b)=>Math.abs(b.change.percent)-Math.abs(a.change.percent))[0],ticks=[-50000000,0,50000000,100000000,150000000,200000000];
 return `<div class="trend-toolbar"><div class="trend-legend">${TREND_METRICS.map(m=>`<button data-trend-metric="${m.id}" aria-pressed="${trendMetrics.includes(m.id)}" class="${trendMetrics.includes(m.id)?'':'muted'}"><i style="--series-color:${m.color}"></i>${m.short}</button>`).join('')}</div><div class="trend-range" aria-label="趋势报告期间">${[['all','近8季'],['2025','2025'],['2024','2024']].map(([id,label])=>`<button data-trend-range="${id}" aria-pressed="${trendRange===id}" class="${trendRange===id?'active':''}">${label}</button>`).join('')}</div></div>
 <div class="trend-plot" id="financial-trend"><span class="trend-unit">亿元</span><svg viewBox="0 0 1000 260" preserveAspectRatio="none" role="img" aria-label="绿的谐波季度财务趋势，2024至2025年；营业收入、归母净利润与经营现金流。具体值可通过下方季度按钮查看。">${ticks.map(v=>{const y=220-(v+5e7)/2.5e8*204;return `<line x1="55" x2="965" y1="${y}" y2="${y}" class="${v===0?'zero-grid':'trend-grid'}"/><text x="39" y="${y+4}" text-anchor="end" class="trend-axis">${(v/1e8).toFixed(1)}</text>`}).join('')}${TREND_METRICS.filter(m=>trendMetrics.includes(m.id)).map(m=>lineSegments(rows,m.id).map(seg=>`<polyline points="${seg.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${m.color}" stroke-width="2" vector-effect="non-scaling-stroke"/>${seg.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3" fill="white" stroke="${m.color}" stroke-width="1.7" vector-effect="non-scaling-stroke"/>`).join('')}`).join('')).join('')}${trendMetrics.includes('revenue')&&notable?`<text x="${points.find(p=>p.id===notable.q.id).x-12}" y="${Math.max(15,points.find(p=>p.id===notable.q.id).y-18)}" text-anchor="end" class="trend-annotation">${notable.q.label} · 收入环比 ${signed(notable.change.percent)}%</text>`:''}<g id="trend-crosshair" visibility="hidden"><line y1="12" y2="220" stroke="#b0b0b0" stroke-dasharray="3 4" vector-effect="non-scaling-stroke"/></g>${points.map(p=>`<text x="${p.x}" y="250" text-anchor="middle" class="trend-axis">${rows.find(q=>q.id===p.id).label}</text>`).join('')}</svg>
 <div class="trend-hit-zones">${rows.map((q,i)=>`<button style="left:${i/(rows.length-1)*100}%;width:${(i===0||i===rows.length-1?50:100)/(rows.length-1)}%;transform:translateX(${i===0?0:i===rows.length-1?-100:-50}%)" data-trend-point="${q.id}" aria-label="${q.label}：营业收入${money(q.values.revenue)}元，查看季度明细" aria-pressed="${trendSelected===q.id}"><span>${q.label}</span></button>`).join('')}</div><div class="trend-tooltip" id="trend-tooltip" role="status" hidden></div></div>
 <div class="trend-foot"><span>公司合并口径 · 非人形收入</span><button id="trend-source-info">数据口径与来源 ↗</button></div>`;
}
function trendTooltip(q){const change=quarterChange(q.id),source=TREND_SOURCES[q.source];return `<div class="trend-tip-head"><strong>${q.label}</strong><span>${q.periodStart} — ${q.periodEnd}</span></div>${TREND_METRICS.filter(m=>trendMetrics.includes(m.id)).map(m=>`<div class="trend-tip-value"><span><i style="--series-color:${m.color}"></i>${m.short}</span><strong>${money(q.values[m.id]/1e4)}<small>万元</small></strong></div>`).join('')}<div class="trend-tip-change">营业收入环比 <b>${change?signed(change.percent)+'%':'未获取前期'}</b><span>${source.status} · 年报第8页</span></div>`;}
function financialTable(){const rows=[...quartersFor(trendRange)].reverse();return `<div class="table-wrap"><table class="financial-table"><thead><tr><th>报告期</th><th>营业收入<small>万元</small></th><th>收入环比</th><th>归母净利润<small>万元</small></th><th>经营现金流<small>万元</small></th><th>来源</th><th></th></tr></thead><tbody>${rows.map(q=>{const change=quarterChange(q.id),source=TREND_SOURCES[q.source],expanded=financialExpanded===q.id;return `<tr data-financial-row="${q.id}" class="${expanded?'expanded':''} ${trendSelected===q.id?'selected-quarter':''}"><td><strong>${q.label}</strong><small>${q.periodStart} — ${q.periodEnd}</small></td><td class="number">${money(q.values.revenue/1e4)}</td><td class="number ${change&&change.percent>0?'number-rise':''}">${change?signed(change.percent)+'%':'—'}</td><td class="number">${money(q.values.profit/1e4)}</td><td class="number">${money(q.values.cash/1e4)}</td><td><span class="${q.source==='GD25Q'?'quarter-replay':'quarter-source'}">${source.status}</span></td><td><button data-expand-quarter="${q.id}" class="row-toggle" aria-expanded="${expanded}">${expanded?'收起 −':'展开 +'}</button></td></tr>${expanded?`<tr class="expanded-detail"><td colspan="7"><div class="financial-detail"><div><span class="inline-label">原始披露 · 人民币元</span><div class="raw-values">${TREND_METRICS.map(m=>`<span>${m.short}<strong>${money(q.values[m.id])}</strong></span>`).join('')}</div><a href="${source.url}#page=8" target="_blank" rel="noopener noreferrer">${source.title} · 第8页 ↗</a><small>披露 ${source.publishedAt} · 本地收录 ${q.recordedAt} · ${q.verification}</small></div><div class="financial-detail-action"><strong>经营变化已披露，人形贡献仍待拆分</strong><p>${change?`收入较上季变化 ${signed(change.delta/1e4)} 万元（${signed(change.percent)}%）。`:'未获取上一季度，不计算环比。'}不能据此确认客户定点或人形业务收入。</p><div class="btnrow"><button class="primary" data-financial-evidence>核查业务证据 ↗</button><button data-topic-compare="green">公司对比 ↗</button><button data-financial-source="${q.source}">口径与计算</button></div></div></div></td></tr>`:''}`}).join('')}</tbody></table></div>`;}
function showTrendSource(id){const sources=id?[TREND_SOURCES[id]]:Object.values(TREND_SOURCES);modal(`<h2>季度财务数据</h2><p>绿的谐波 · 688017.SH · 公司合并口径 · 单季度 · 人民币。曲线只连接8个已披露观测值，不插补月度数据，不代表人形收入。</p>${sources.map(s=>`<p><a href="${s.url}#page=8" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><br>${s.locator}<br>披露 ${s.publishedAt} · 版本 ${s.version}</p>`).join('')}<p>图表单位：亿元；明细单位：万元；展开后保留原始元值。收入环比 =（本季收入 ÷ 上季收入 − 1）×100%。2024 Q1缺少前季，不填充环比。</p><p>FY2025使用更正后年报回放；未比对原版，不判断哪些季度字段曾被更正。此处展示不改变业务证据版本与已存研究。</p><p class="small">本图保留公司官方披露；iFinD财务快照在公司对比页独立展示。内部指标表预留公司、指标、频率、期间、币种、原值、版本与缺值原因字段，未冒用iFinD指标代码。<a href="https://ftwc.51ifind.com/gwstatic/static/ds_web/quantapi-web/" target="_blank" rel="noopener noreferrer">iFinD官方数据接口说明 ↗</a></p>`);}
function businessShareChart(){const x=shareSeries(shareCompany)||shareSeries('green');return `<div class="share-toolbar"><select id="share-company" aria-label="业务结构公司"><option value="green" ${shareCompany==='green'?'selected':''}>绿的谐波</option><option value="hds" ${shareCompany==='hds'?'selected':''}>Harmonic Drive</option></select><span>${x.period} · 占合并收入</span></div><div class="share-chart" aria-label="${x.company}业务收入占比">${x.rows.map(r=>`<button class="share-row" ${r.claim?`data-claim="${r.claim}"`:'data-computed-share="true"'} aria-label="${r.name} ${r.value.toFixed(2)}%"><span class="share-name">${r.name}</span><span class="share-track"><i class="${r.kind}" style="width:${r.value}%"></i><span class="chart-tooltip">${r.value.toFixed(2)}% · ${x.source==='GD24'?'计算值':'披露值'}</span></span><strong>${r.value.toFixed(2)}<small>%</small></strong></button>`).join('')}<div class="share-axis"><span>0</span><span>25</span><span>50</span><span>75</span><span>100%</span></div></div><div class="chart-caption">${srcButton(x.source,'披露来源')}<span>保留披露口径；占比四舍五入可能不恰为100%。</span></div>`;}
function shipmentChart(){const d=updateDelta(),added=data.claims.some(c=>c.id===OFFICIAL_UPDATE.id);return `<div class="shipment-meta"><span>绿的谐波 · 产品组年度观察</span><strong>+${d.percent.toFixed(2)}% <small>产品组收入</small></strong></div><div class="annual-chart" aria-label="FY2024 3.254亿元，FY2025 4.765亿元">${[[2024,d.before,'dark'],[2025,d.after,'accent']].map(([year,value,color])=>`<button class="annual-column" data-year-fact="${year}"><strong>${(value/1e8).toFixed(3)} <small>亿元</small></strong><span class="annual-track"><i class="${color}" style="height:${value/6e8*100}%"></i></span><span>FY${year}${year===2025&&!added?' · 回放候选':''}</span><small>${year===2024?'谐波减速器及金属部件':'谐波减速器及金属件'}</small></button>`).join('')}</div><div class="chart-caption"><a href="${OFFICIAL_UPDATE.source.url}" target="_blank" rel="noopener noreferrer">更正后年报 ↗</a><span>项目名分别保留；范围仍需核查，非人形收入。</span></div>`;}
function evidenceStateChart(){return `<div class="evidence-status-list">${['C07','C08','C09'].map(id=>{const c=data.claims.find(x=>x.id===id),co=data.companies.find(x=>x.id===c.company);return `<button data-claim="${id}"><span><strong>${co.name}</strong><small>${c.concept}</small></span>${badge(c.grade)}</button>`}).join('')}</div><div class="state-conclusion"><strong>按公司 × 概念判断</strong><span>研发、预期和收入缺口分别展示</span></div><div class="chart-caption"><span>证据等级不是概率，不代表投资评级。</span></div>`;}
function pathLabels(t){return t.id==='growth'?['披露事实','收入归因','证据缺口','后续验证']:t.id==='humanoid'?['研发事实','市场展望','收入缺口','后续验证']:['外部变化','产业环节','公司业务','财务指标'];}
function pathSteps(t){if(t.scenario)return data.scenarios.find(x=>x.id===t.scenario).steps;if(t.id==='growth')return ['产品组收入增长','下游应用未拆分','客户定点未核实','等待应用与合同披露'];return ['Tesla研发Optimus','HDS展望人形市场','绿的人形收入未拆分','核查合同、交付与收入'];}
function topicPathChart(t){return `<div class="mini-path">${pathSteps(t).map((v,i)=>`<div><span>${pathLabels(t)[i]}</span><strong>${v}</strong></div>`).join('')}</div><div class="chart-caption">${srcButton(activeClaim(t.claims[0]).source,'机制与证据')}<span>条件性路径，非确定业绩影响。</span></div>`;}
function topicCompanyTable(t,claims){return `<div class="table-wrap"><table class="topic-company-table"><thead><tr><th>公司 / 市场</th><th>已验证业务</th><th>证据</th><th>人形关联 / 待验证</th><th></th></tr></thead><tbody>${claims.map(c=>{const co=data.companies.find(x=>x.id===c.company),source=data.sources.find(x=>x.id===c.source),impact=t.impacts[c.id]||t.impacts[t.claims.find(id=>data.claims.find(x=>x.id===id)?.company===c.company)]||t.boundary;return `<tr class="${hotExpanded===c.id?'expanded':''}"><td><strong>${co.name}</strong><small>${co.ticker}</small></td><td><strong>${esc(c.concept)}</strong><small>${esc(periodLabel(c))}</small></td><td>${badge(c.grade)}${c.validity?.conflict?'<small>来源列示冲突</small>':''}</td><td class="impact-cell">${impact}</td><td><button class="row-toggle" data-expand-claim="${c.id}" aria-expanded="${hotExpanded===c.id}">${hotExpanded===c.id?'收起 −':'展开 +'}</button></td></tr>${hotExpanded===c.id?`<tr class="expanded-detail"><td colspan="5"><div class="evidence-inline"><div><span class="inline-label">披露事实 · ${c.id}</span><p>${esc(c.text)}</p><small>${esc(c.locator)}</small>${c.quote?`<blockquote class="source-quote">${esc(c.quote)}</blockquote><small>${esc(c.quoteNote)}</small>`:''}<a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a></div><div><span class="inline-label">使用边界</span><p>${esc(c.boundary)}</p><div class="btnrow"><button data-topic-compare="${co.id}">公司对比 ↗</button>${t.scenario?`<button data-topic-scenario="${t.scenario}" data-context-claim="${c.id}">财务观察 ↗</button>`:''}${claimButton(c,'完整证据')}</div></div></div></td></tr>`:''}`}).join('')}</tbody></table></div>`;}
function topicChain(t){return `<div class="topic-chain">${data.levels.map(l=>`<section><h3>${l.name}</h3>${l.nodes.filter(n=>t.nodes.includes(n.id)).map(n=>`<button data-topic-node="${n.id}"><strong>${n.name}</strong><span>${n.sub}</span><small>${nodeEvidenceLabel(data.claims.filter(c=>c.node===n.id))}</small></button>`).join('')||'<p class="small">当前专题不涉及该层级</p>'}</section>`).join('')}</div><div class="workbench-note">${srcButton('method','分类口径')}</div>`;}
function topicTransmission(t){const sc=data.scenarios.find(x=>x.id===t.scenario),sample=sampleById(t.sample);return `<div class="topic-transmission"><div class="full-path">${pathSteps(t).map((x,i)=>`<div><small>${pathLabels(t)[i]}</small><strong>${x}</strong><small class="edge-state">${sc?.edgeStates[i]||'待验证'}</small></div>`).join('')}</div><div class="transmission-notes"><div><h3>观察指标</h3>${(sc?.metrics||sample.gaps).map(x=>`<p>${x}</p>`).join('')}</div><div><h3>${sc?'反向条件':'待验证'}</h3><p>${sc?.counter||sample.watch}</p>${sc?`<button data-topic-scenario="${sc.id}">打开情景分析 ↗</button>`:''}</div></div></div>`;}
function topicActivity(t,claims){const sourceIds=[...new Set(claims.map(c=>c.source))],candidateRelevant=claims.some(c=>c.company==='green'&&c.node==='reducer'),added=data.claims.some(c=>c.id===OFFICIAL_UPDATE.id);return `<div class="research-timeline">${sourceIds.map(id=>{const source=data.sources.find(x=>x.id===id);return `<div class="timeline-row"><time>${source.date}</time><div><strong>${source.title}</strong><p>${id.startsWith('U_')?'本机已入库 · 判断待单独复核':'已收录 · 历史研究基准'}</p>${srcButton(id,'原文定位')}</div><span class="badge neutral">${id.startsWith('U_')?'已复核':'基准材料'}</span></div>`}).join('')}${candidateRelevant&&!added?`<div class="timeline-row candidate"><time>${OFFICIAL_UPDATE.source.date}</time><div><strong>绿的谐波 FY2025 · 更正后年报</strong><p>“谐波减速器及金属件”收入4.76亿元 · 同比约46.42%</p><button id="topic-review-update">载入复核 ↗</button></div><span class="badge yellow">待入库候选</span></div>`:''}<div class="workbench-note">历史披露回放；入库时间单独记录。未载入FY2025原版，不判断更正字段。跨年度数据并存。</div></div>`;}
function openTopicUpdate(){view='updates';if(data.archivedClaims.some(c=>c.id===OFFICIAL_UPDATE.id)){render();showRestore();return;}if(!data.claims.some(c=>c.id===OFFICIAL_UPDATE.id)){draft=validateUpdate(OFFICIAL_UPDATE,data);updateText=JSON.stringify(draft,null,2);updateMode='form';updateError=''}render();window.scrollTo(0,0);}
function saveTopicResearch(){const t=topicById(hotTopic),sample=sampleById(t.sample);try{if(!notebook.some(r=>r.id===sample.id))saveNotebook([...notebook,newResearchRecord(sample,data)]);view='notebook';render();showNotebook(sample.id)}catch(e){toast('保存失败：'+e.message)}}
function financialAppendix(){return '\n## 季度经营观察（当前展示数据，不作为人形业务归因）\n\n单位：人民币元。合并口径、单季度；FY2025为历史披露回放。\n\n|期间|营业收入|归母净利润|经营现金流|来源|\n|---|---:|---:|---:|---|\n'+quartersFor(trendRange).map(q=>'|'+q.periodStart+' — '+q.periodEnd+'|'+q.values.revenue+'|'+q.values.profit+'|'+q.values.cash+'|['+TREND_SOURCES[q.source].version+']('+TREND_SOURCES[q.source].url+'#page=8)|').join('\n')+'\n\n来源均为年报第8页。未比较FY2025原版与更正版，不判断字段更正。公司披露与iFinD快照分开保存；这些观察不自动改写已存研究或业务证据等级。\n';}
function exportHotspot(){const t=topicById(hotTopic);if(hotAnswer){const text='# '+hotQuestion+'\n\n'+hotAnswer.text+'\n\n'+hotAnswer.claims.map(c=>'['+c.id+'] '+c.period+' '+c.text+'\n'+c.boundary+'\n'+c.locator+'\n'+(data.sources.find(x=>x.id===c.source)?.url||'')).join('\n\n');download('ChainLens-query.md',text,'text/markdown');return}const r=newResearchRecord(sampleById(t.sample),data),content=researchMarkdown(r,data)+'\n## 专题边界\n'+t.boundary+'\n\n## 传导路径\n'+pathSteps(t).join(' → ')+'\n'+(t.id==='growth'?financialAppendix()+'\nFY2025历史披露回放：'+OFFICIAL_UPDATE.source.url+'\nFY2025谐波减速器及金属件476,486,798.69元；FY2024谐波减速器及金属部件325,415,663.13元。保留名称差异，非人形应用贡献；未载入原版，不判断该字段是否更正。\n':'');modal(`<div class="eyebrow">研究交付 · 离线样例</div><h2>${t.question}</h2><textarea class="export-preview" aria-label="专题简报 Markdown" readonly>${esc(content)}</textarea><div class="modal-actions"><button class="primary" id="download-topic-file">下载 Markdown</button></div>`);$('#download-topic-file').onclick=()=>download('ChainLens-'+t.id+'.md',content,'text/markdown');}
function bindTrends(){
 document.querySelectorAll('[data-trend-metric]').forEach(b=>b.onclick=()=>{const id=b.dataset.trendMetric;if(trendMetrics.includes(id)){if(trendMetrics.length===1){toast('至少保留一项指标');return}trendMetrics=trendMetrics.filter(x=>x!==id)}else trendMetrics.push(id);render()});
 document.querySelectorAll('[data-trend-range]').forEach(b=>b.onclick=()=>{trendRange=b.dataset.trendRange;trendSelected=financialExpanded=null;render()});
 const plot=$('#financial-trend'),tooltip=$('#trend-tooltip'),hair=$('#trend-crosshair');
 const show=q=>{const rows=quartersFor(trendRange),i=rows.findIndex(x=>x.id===q.id),x=55+i*910/(rows.length-1);tooltip.innerHTML=trendTooltip(q);tooltip.hidden=false;tooltip.style.left=`${Math.max(1,Math.min(70,x/10-12))}%`;hair.setAttribute('visibility','visible');hair.querySelector('line').setAttribute('x1',x);hair.querySelector('line').setAttribute('x2',x);};
 document.querySelectorAll('[data-trend-point]').forEach(b=>{const q=QUARTERS.find(x=>x.id===b.dataset.trendPoint);b.onpointerenter=()=>show(q);b.onfocus=()=>show(q);b.onclick=()=>{trendSelected=q.id;financialExpanded=q.id;hotTab='financials';render();document.querySelector(`[data-financial-row="${q.id}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})};b.onkeydown=e=>{if(e.key==='Escape'){tooltip.hidden=true;hair.setAttribute('visibility','hidden')}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const all=[...document.querySelectorAll('[data-trend-point]')],i=all.indexOf(b),next=all[i+(e.key==='ArrowRight'?1:-1)];next?.focus();}}});
 if(plot)plot.onpointerleave=()=>{tooltip.hidden=true;hair.setAttribute('visibility','hidden');};
 document.querySelectorAll('[data-expand-quarter]').forEach(b=>b.onclick=()=>{financialExpanded=financialExpanded===b.dataset.expandQuarter?null:b.dataset.expandQuarter;trendSelected=financialExpanded;render()});
 document.querySelectorAll('[data-financial-evidence]').forEach(b=>b.onclick=()=>{hotTab='companies';hotExpanded='C01';render();document.querySelector('.research-workbench')?.scrollIntoView({behavior:'smooth',block:'start'})});
 document.querySelectorAll('[data-financial-source]').forEach(b=>b.onclick=()=>showTrendSource(b.dataset.financialSource));
 if($('#trend-source-info'))$('#trend-source-info').onclick=()=>showTrendSource();
}
function bindHotspot(){if(view!=='hotspot')return;bindTrends();document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>selectTopic(b.dataset.topic));$('#topic-question-form').onsubmit=e=>{e.preventDefault();hotQuestion=$('#topic-question').value.trim();if(!hotQuestion){toast('请输入研究问题');return}const result=retrieve(hotQuestion,data),matched=result.refused?null:matchTopic(hotQuestion);if(result.profiles?.length){view='ai';chatQuestion=hotQuestion;answer={...result,mode:'rules'};render();window.scrollTo(0,0)}else if(matched){const question=hotQuestion;selectTopic(matched);hotQuestion=question;render()}else{hotAnswer=result;render()}};document.querySelectorAll('[data-chart-mode]').forEach(b=>b.onclick=()=>{hotChart=b.dataset.chartMode;hotTab=hotChart==='trend'?'financials':hotChart==='growth'?'companies':hotTab;render()});if($('#share-company'))$('#share-company').onchange=e=>{shareCompany=e.target.value;render()};document.querySelectorAll('[data-expand-claim]').forEach(b=>b.onclick=()=>{hotExpanded=hotExpanded===b.dataset.expandClaim?'':b.dataset.expandClaim;render()});document.querySelectorAll('[data-topic-node]').forEach(b=>b.onclick=()=>{view='chain';selected=b.dataset.topicNode;query=grade=market='';render();window.scrollTo(0,0)});document.querySelectorAll('[data-topic-compare]').forEach(b=>b.onclick=()=>{pair=[b.dataset.topicCompare,b.dataset.topicCompare==='green'?'hds':'green'];view='compare';render();window.scrollTo(0,0)});document.querySelectorAll('[data-topic-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.topicScenario;contextClaim=b.dataset.contextClaim||null;view='scenario';render();window.scrollTo(0,0)});if($('#save-topic'))$('#save-topic').onclick=saveTopicResearch;if($('#topic-next'))$('#topic-next').onclick=()=>{hotTab=topicById(hotTopic).scenario?'transmission':'companies';render();document.querySelector('.research-workbench')?.scrollIntoView({behavior:'smooth',block:'start'})};if($('#topic-review-update'))$('#topic-review-update').onclick=openTopicUpdate;document.querySelectorAll('[data-computed-share]').forEach(b=>b.onclick=()=>toast('其他业务为 100% 减去已列业务占比；不是新增披露项'));document.querySelectorAll('[data-year-fact]').forEach(b=>b.onclick=()=>{if(b.dataset.yearFact==='2024')showClaim('C01');else modal(`<h2>绿的谐波 FY2025 · 收入候选</h2><p>${OFFICIAL_UPDATE.text}</p><p>${OFFICIAL_UPDATE.boundary}</p><a href="${OFFICIAL_UPDATE.source.url}" target="_blank" rel="noopener noreferrer">披露原文 ↗</a>`)});document.querySelectorAll('[data-evidence-state]').forEach(b=>b.onclick=()=>modal(`<h2>${b.dataset.evidenceState} · ${GRADES[b.dataset.evidenceState].label}</h2><p>${GRADES[b.dataset.evidenceState].desc}</p>`));document.querySelectorAll('[data-research-tab]').forEach(b=>b.onclick=()=>{hotTab=b.dataset.researchTab;render()});}

function stats(){const unique=cs=>new Set(cs.map(c=>c.relationId)).size;return `<div class="stats">${[['深度核查公司',data.companies.length],['业务 / 预期关系',unique(data.claims.filter(c=>c.grade!=='E'))],['证据缺口',unique(data.claims.filter(c=>c.grade==='E'))],['基准材料',base.sources.length]].map(([label,n])=>`<div class="stat"><span class="label">${label}</span><strong class="number">${String(n).padStart(2,'0')}</strong></div>`).join('')}</div>`;}

function assistant(){return `<aside class="right-panel"><section class="card assistant"><div class="card-head"><h2>✧ AI 研究助手</h2><span class="badge neutral">${online?'在线模型已配置':'离线回放 / 检索'}</span></div><div class="card-body"><label for="question" class="hidden">研究问题</label><textarea id="question" aria-label="输入公司或概念问题" placeholder="输入研究问题…" maxlength="1000">${esc(chatQuestion)}</textarea><button id="ask" class="primary" ${busy?'disabled':''}>${busy?'检索中…':'检索证据'}</button><div class="sample-links"><span>研究样例</span>${RESEARCH_SAMPLES.map(c=>`<button data-research-sample="${c.id}">${c.short} ↗</button>`).join('')}</div>${online?'<label class="small"><input type="checkbox" id="use-model"> 使用在线 AI（公开证据）</label>':''}${answer?`<div class="answer" aria-live="polite"><span class="badge ${answer.mode==='AI'?'orange':'neutral'}">${answer.mode==='AI'?'AI · 待复核':'检索结果'}</span><p style="margin-top:10px">${esc(answer.text)}</p>${answer.claims.map(c=>`<div class="answer-item"><strong>${esc(data.companies.find(x=>x.id===c.company)?.name)} · ${esc(c.concept)}</strong>${badge(c.grade)}<p>${esc(c.text)}</p>${claimButton(c,'['+c.id+'] 来源')}</div>`).join('')}${answer.modelText?`<div class="info-box" style="margin-top:12px;white-space:pre-wrap">${esc(answer.modelText)}</div>`:''}</div>`:''}<details class="inline-details"><summary>数据范围</summary><p>3 份基准披露，报告期分别标注。${online?'在线模型输出需复核。':'关键词检索与规则整理；研究样例是开发阶段 AI 分析回放，未启用在线 AI。'}</p></details></div></section></aside>`}
function chainView(){let html=chainViewUI(data,{node:selected||'reducer',tab:chainTab,expanded:chainExpanded,filter:chainFilter});html=html.replace(/<section class="chain-atlas"[\s\S]*?<\/section>/,map=>'<details class="inline-details"><summary>功能分层</summary>'+map+'</details>');const ids=chainRelationsForView();html=html.replace('<section class="chain-ledger"',nodeGrowth(ifind,ids)+'<section class="chain-ledger"');return evidenceMap(data)+html;}
function chainRelationsForView(){return CATALOG.filter(c=>c.nodes.includes(selected||'reducer')).map(c=>c.id);}

function compareRows(a,b){const parts=[a.id,b.id];if(parts.includes('green')&&parts.includes('hds'))return [['可比业务','两者均披露减速器与机电一体化产品收入，可研究精密传动和执行器。','比较需限定相同应用与型号；并非所有产品都用于人形机器人。'],['产品与技术','绿的谐波减速器、HDS精密减速器在旋转传动功能存在交集。','绿的收入含金属部件；HDS减速器与机电产品组范围不同，不直接比较单价。'],['客户与供应链','可观察机器人与工业自动化需求、国产替代及客户验证。','下游分布、地域与客户结构未统一；没有核实两者与Tesla的直接采购关系。'],['财务与期间','绿的基准2024-01-01—2024-12-31；2025年度观察2025-01-01—2025-12-31。HDS2024-04-01—2025-03-31。相同2025标签不代表同期。','期间、产品范围、合并范围和指标定义需对齐；会计差异与一次性因素需可解释。不满足时仅并列展示，不排名。']];const supplier=parts.includes('green')?'绿的谐波':'Harmonic Drive';return [['产业关联',supplier+'提供传动或执行器相关产品；Tesla研发Optimus整机。','这是跨环节研究参照，不是同业财务可比组。'],['产品边界','零部件供应商与整机厂处于不同功能层级。','单机用量、技术方案与采购份额均待核实，不能将上下游直接等同。'],['业务关系','可研究整机商业化对零部件需求的条件性影响。','当前样本未核实'+supplier+'对Tesla的直接供货；链条连线不是订单证据。'],['财务与期间','各公司保留各自报告期、原币种和会计准则。','Tesla集团收入不是Optimus收入；2025年10-K披露Bots尚未商业化，不能计算人形收入倍数。']];}
function compareView(){return comparisonView(ifind,{pair,metric:compareMetric,scope:compareScope,expanded:compareExpanded,quarter:compareQuarter,error:ifindError});}

function contextBanner(){const c=data.claims.find(x=>x.id===contextClaim);if(!c)return '';const co=data.companies.find(x=>x.id===c.company);return `<div class="context-banner"><strong>${co.name} · ${esc(c.concept)}</strong>${claimButton(c,'业务证据')}</div>`}
function unquantifiedImpact(s){const needs=s.id==='policy'?['政策原文、对象与适用资格','采购合同、验收与支付条件','补助与营业收入的会计边界']:['BOM与采购合同、制造良率','产品ASP、单位成本与稼动率','产品组合、库存成本与研发费用'];return `<section class="card"><div class="card-head"><h2>量化条件</h2><span class="badge yellow">参数待补充</span></div><div class="card-body">${needs.map(x=>`<div class="list-item">${x}</div>`).join('')}<p class="small" style="margin:20px 0">数据不足，暂不估算财务影响金额。</p><button data-view="updates">补充证据</button></div></section>`;}
function scenarioView(){const s=data.scenarios.find(x=>x.id===scenario);return `${contextClaim?contextBanner():''}<div class="scenario-tabs">${data.scenarios.map(x=>`<button data-scenario="${x.id}" class="${x.id===scenario?'active':''}">${x.name}</button>`).join('')}</div><section class="card"><div class="card-head"><h2>影响路径</h2><div><span class="badge yellow">条件性情景</span> ${srcButton(s.source,'来源')}</div></div><div class="flow">${s.steps.map((x,i)=>`<div class="flow-step"><span>${['外部变化','产业环节','公司业务','财务影响'][i]}</span>${x}<small class="edge-state">${s.edgeStates[i]}</small></div>`).join('')}</div></section>${impactGrid(s,exposure)}<div class="two-col"><section class="card"><div class="card-head"><h2>观察指标</h2></div><div class="card-body">${s.metrics.map(m=>`<div class="list-item">${m}</div>`).join('')}<div class="counter-condition"><strong>反向条件</strong><p>${s.counter}</p><small>${s.lag}</small></div></div></section>${s.id==='ramp'?`<section class="card"><div class="card-head"><h2>收入敏感性</h2><span class="badge neutral">用户假设</span></div><div class="card-body"><p class="small">${s.baseLabel} · ${s.base.toLocaleString('en-US')} ${s.unit} ${srcButton(s.baseSource,'基准收入来源')}</p>${[['exposure','受影响收入占比',exposure,0,100],['volume','销量变化',volume,-50,50],['price','价格变化',price,-30,30]].map(([id,t,v,min,max])=>`<div class="slider-row"><label for="${id}">${t}<b id="${id}-value">${v}%</b></label><input id="${id}" type="range" min="${min}" max="${max}" value="${v}" step="1"></div>`).join('')}<div class="calc-result" id="calc-result"></div><details class="inline-details"><summary>公式与假设</summary><p>Δ收入 = 基准收入 × 暴露比例 × [(1+销量变化) × (1+价格变化) − 1]。未考虑汇率、产品组合与收入确认时点。${s.boundary}</p></details></div></section>`:unquantifiedImpact(s)}</div>`}
function deliveryView(){return `<div class="resource-grid">${[['⇧','部署说明','本地运行 / 转成公网URL','部署说明.md'],['▶','产品演示','连续操作 · MP4','ChainLens-demo-96s.mp4'],['↗','源代码','完整源码 ZIP','ChainLens-source.zip'],['⎇','Git 源码镜像','可独立克隆 · Git bundle','ChainLens-review.bundle'],['▤','产品说明','README','README.md'],['◇','AI 验证记录','使用与验证','AI使用与验证记录.md'],['✓','测试说明','功能、异常与边界','测试说明.md'],['⌕','数据口径','数字与官方来源','数据与口径.md'],['◈','产品设计','定位、取舍与评估','产品设计与面试讲解.md']].map(([icon,title,sub,file])=>`<a class="resource-card" href="deliverables/${file}" target="_blank"><span class="resource-icon">${icon}</span><strong>${title}</strong><small>${sub}</small><span class="resource-arrow">↗</span></a>`).join('')}</div><section class="card"><div class="card-head"><h2>数据与运行状态</h2></div><div class="card-body status-list"><p><span>访问方式</span>GitHub Pages / 本地运行</p><p><span>数据</span>${ifind?"iFinD财务10家公司 / 公告7条片段；":""}13家企业资料 / 3家深度证据样本</p><p><span>研究助手</span>${online?'模型已配置，输出需复核':'本地证据检索；在线 AI 未启用'}</p><p><span>证据更新</span>当前浏览器存储；刷新保留，更换浏览器需恢复备份</p><p><span>源码仓库</span><a href="deliverables/ChainLens-review.bundle">离线Git源码镜像 ↗</a> · 可独立克隆</p></div></section><details class="inline-details"><summary>覆盖范围与已知边界</summary><p>iFinD已实际取数并导入快照；网页未直接调用MCP。扶摇未接入。分类未覆盖全产业，跨年度事实并存，更正仅替代声明字段。在线 AI 适配尚未完成真实调用验证。研究样例为开发阶段 AI 分析回放；研究台账支持判断、跟踪、版本与关联更新提醒。</p><a href="deliverables/要求覆盖与UX核查.md" target="_blank">完整核查记录 ↗</a></details>`}
function readableUpdateError(message){const names={id:'记录编号',company:'公司',node:'产业环节',concept:'业务 / 概念',text:'材料支持的结论',grade:'证据等级',period:'报告期',boundary:'使用限制',locator:'原文位置',title:'材料名称',date:'发布日期',publisher:'发布机构'};return String(message).replace(/(?:来源)?字段缺失或超长：(\w+)/,(_,key)=>'请填写'+(names[key]||key)+'，并确认内容长度符合要求。');}
function formCandidate(){try{return JSON.parse(updateText)||{}}catch{return {}}}
function evidenceForm(){const x=formCandidate(),source=x.source||{};const field=(key,title,value,placeholder='',wide=false,type='text')=>`<label class="${wide?'wide':''}">${title}<input data-evidence-field="${key}" value="${esc(value??'')}" placeholder="${placeholder}" type="${type}" maxlength="1000"></label>`;const select=(key,title,values,value)=>`<label>${title}<select data-evidence-field="${key}">${values.map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${label}</option>`).join('')}</select></label>`;return `<div class="evidence-form">${select('company','公司',data.companies.map(c=>[c.id,c.name]),x.company||'green')}${select('node','研究环节',data.levels.flatMap(l=>l.nodes).map(n=>[n.id,n.name]),x.node||'reducer')}${field('concept','业务关系',x.concept,'例如：行星滚柱丝杠')}${field('disclosedName','披露项目原名',x.disclosedName,'按原文；不可自行拆分')}${field('periodStart','报告期起',x.periodStart,'',false,'date')}${field('periodEnd','报告期止',x.periodEnd,'',false,'date')}${select('evidenceCategory','证据类别',[['','不适用 / 缺口'],...['收入','订单','交付','产品研发','表态'].map(v=>[v,v])],x.evidenceCategory||'')}${field('businessStage','具体阶段',x.businessStage,'研发 / 送样 / 定点 / 正式订单 / 交付 / 收入确认')}${select('supportDirection','支持方向',['支持','否认','不能判断'].map(v=>[v,v]),x.supportDirection||'不能判断')}${select('updateType','变化类型',[['new','新增事实'],['annual','跨报告期'],['revision','同报告期字段更正']],x.updateType||'new')}${field('source.title','材料名称',source.title)}${field('source.date','披露日期',source.date,'',false,'date')}${field('source.url','原文链接（HTTPS）',source.url,'https://...',true,'url')}${field('locator','原文位置',x.locator,'页码 / 章节 / 表名',true)}<label class="wide">原文短摘录<textarea data-evidence-field="quote" maxlength="3000">${esc(x.quote||'')}</textarea></label><label class="wide">事实结论<textarea data-evidence-field="text" maxlength="3000">${esc(x.text||'')}</textarea></label><label class="wide">使用边界<textarea data-evidence-field="boundary" maxlength="3000">${esc(x.boundary||'')}</textarea></label><details class="wide inline-details"><summary>高级：绑定字段、口径与来源版本</summary><div class="evidence-form">${field('relationId','关系 ID',x.relationId,'公司×产品或客户')}${field('metricKey','事实字段',x.metricKey,'例如：revenue')}${field('period','报告期标签',x.period,'例如：FY2025')}${field('sourceVersion','来源版本',x.sourceVersion,'例如：GD25-corrected-20260710')}${field('scope','披露范围',x.scope,'无法拆分时保留原范围',true)}${field('amount','金额（可空）',x.amount,'未披露时留空',false,'number')}${select('currency','币种',[['','不适用'],['CNY','人民币'],['JPY','日元'],['USD','美元']],x.currency||'')}${select('missingReason','缺值原因',['未披露','未获取','不适用'].map(v=>[v,v]),x.missingReason||'未获取')}${field('source.publisher','披露机构',source.publisher)}${select('grade','页面摘要',Object.entries(GRADES).map(([g,v])=>[g,g+' · '+v.label]),x.grade||'E')}</div><p class="small">缺口核查记录、修订字段及同时有效性标记可用高级JSON编辑；新事实须补齐这些必要字段。</p></details></div>`;}

function collectEvidenceForm(){const old=formCandidate(),x={...old,id:old.id||'UPDATE_'+Date.now(),source:{...old.source},validity:old.validity||{conflict:false,superseded:false},missingReason:old.missingReason||'未获取',factVersion:old.factVersion||1,reviewStatus:'待复核',supersedes:old.supersedes||null};document.querySelectorAll('[data-evidence-field]').forEach(el=>{const [key,part]=el.dataset.evidenceField.split('.');if(part){x[key]??={};x[key][part]=el.value.trim();}else x[key]=key==='amount'?(el.value.trim()===''?null:Number(el.value)):['evidenceCategory','currency'].includes(key)?(el.value.trim()||null):el.value.trim();});if(x.amount!==null&&x.amount!==undefined)x.missingReason=null;return x;}

function updatesView(){return `${officialUpdatePanel()}<div class="two-col"><section class="card"><div class="card-head"><h2>新增证据</h2><button id="sample" class="link-button">演练</button></div><div class="card-body"><div class="form-mode"><button id="mode-form" class="${updateMode==='form'?'active':''}">表单</button><button id="mode-json" class="${updateMode==='json'?'active':''}">高级 JSON</button></div>${updateMode==='form'?evidenceForm():''}<div class="${updateMode==='form'?'hidden':''}"><label for="update-json" class="small">JSON 记录</label><textarea id="update-json" class="update-editor" spellcheck="false" placeholder="可点击填写示例查看格式">${esc(updateText)}</textarea></div><div class="btnrow" style="margin-top:12px"><button class="primary" id="validate">预览与核对</button><label class="small" style="cursor:pointer">导入 JSON <input id="upload" type="file" accept=".json,application/json" style="max-width:140px"></label></div>${updateError?`<p class="error" style="margin-top:15px" role="alert">${esc(updateError)}</p>`:''}</div></section><div><section class="card"><div class="card-head"><h2>待复核</h2><span class="badge neutral">人工确认</span></div><div class="card-body">${draft?`<span class="badge orange">待复核</span><h3 style="margin:14px 0">${esc(data.companies.find(c=>c.id===draft.company).name)} · ${esc(draft.concept)}</h3>${badge(draft.grade)}${draft.validity?.conflict?'<span class="badge yellow">来源列示冲突</span>':''}<p class="small" style="margin:13px 0">${esc(draft.text)}</p><div class="info-box">来源：${esc(draft.source.title)}<br>报告期：${esc(draft.period)}<br>定位：${esc(draft.locator)}<br>边界：${esc(draft.boundary)}<br>${draft.quote?'原句：'+esc(draft.quote)+'<br>':''}<a href="${esc(draft.source.url)}" target="_blank" rel="noopener noreferrer">打开原始来源 ↗</a></div><div class="journal-form"><label>复核人 / 署名（自填）<input id="evidence-reviewer" maxlength="100"></label><label>复核理由<textarea id="evidence-reason" maxlength="1000"></textarea></label></div><label class="check"><input type="checkbox" id="review">已核对原文、归属与证据等级</label><button class="primary" id="approve" disabled>确认入库</button>`:'<div class="empty">暂无待复核证据</div>'}</div></section><section class="card"><div class="card-head"><h2>版本记录</h2><button class="link-button" id="rollback" ${history.length?'':'disabled'}>恢复指定版本</button></div><div class="card-body">${history.length?history.slice().reverse().map((h,i)=>`<div class="log"><strong>操作 ${history.length-i} · ${h.type==='restore'?'恢复版本':esc(h.claim.concept)}</strong><br>${h.type==='add'?'历史披露入库':'恢复操作'} · ${esc(h.at)}<br>${esc(h.reviewer)} · ${esc(h.reason)}${h.hash?'<br>SHA-256 '+esc(h.hash.slice(0,18))+'…':''}</div>`).join(''):'<p class="small">初始基准 · 暂无本机操作</p>'}<p class="small" style="margin-top:15px;font-size:10px">本浏览器保存 · 恢复操作留痕</p></div></section></div></div><section class="card"><div class="card-head"><h2>证据备份与连接</h2></div><div class="card-body"><div class="btnrow"><span class="badge red">官方年报 · 内置快照</span><span class="badge neutral">扶摇 · 未接入</span><span class="badge neutral">iFinD MCP · 未接入</span><span class="badge ${online?'red':'neutral'}">在线模型 · ${online?'本地服务已配置':'未连接'}</span></div><details class="inline-details"><summary>保存与恢复边界</summary><p>公共基准对所有访问者相同；证据操作与研究保存于当前网址、当前浏览器的localStorage。刷新保留，换浏览器、设备或网址不共享。导出证据操作与研究台账两份备份后可恢复；不含浏览器密码、密钥或账户。清理浏览器数据会丢失本机记录。恢复版本追加操作记录，保留后续历史。</p></details><details class="inline-details"><summary>连接详情</summary><p>当前使用官方年报快照与本地检索。在线模型需在服务端配置密钥，尚无真实调用验证；付费数据接口未接入。</p></details><div class="btnrow" style="margin-top:12px"><button id="export-history">导出备份</button><label class="small">恢复备份 <input id="restore-history" type="file" accept=".json,application/json" style="max-width:165px"></label></div></div></section>`}

function saveNotebook(next){const validated=validateNotebook(next);localStorage.setItem('chainlens-humanoid-notebook-v2',JSON.stringify(validated));notebook=validated;}
function officialUpdatePanel(){const added=data.claims.some(c=>c.id===OFFICIAL_UPDATE.id),known=added||data.archivedClaims.some(c=>c.id===OFFICIAL_UPDATE.id),delta=updateDelta();return `<section class="card update-candidate"><div class="candidate-head"><div><span class="badge yellow">历史披露回放</span><h2>绿的谐波 · 产品组年度观察</h2><p>历史披露回放 · FY2024 → FY2025 · 来源披露 ${OFFICIAL_UPDATE.source.date} <a href="${OFFICIAL_UPDATE.source.url}" target="_blank" rel="noopener noreferrer">巨潮原文 ↗</a></p></div><button id="load-official" class="primary" ${known?'disabled':''}>${added?'已入库':known?'历史已保留 · 可恢复':'载入复核'}</button></div><div class="delta-strip"><div><small>FY2024 · 谐波减速器及金属部件</small><strong>${(delta.before/1e8).toFixed(3)} <span>亿元</span></strong></div><span>→</span><div><small>FY2025 · 谐波减速器及金属件</small><strong>${(delta.after/1e8).toFixed(3)} <span>亿元</span></strong></div><div><small>按所列数值计算</small><strong class="amber">+${delta.percent.toFixed(2)}%</strong></div><p>增长不等于人形应用贡献<br>跨报告期观察 · 非更正字段比较</p></div><details class="inline-details" style="padding:0 20px 15px"><summary>年度观察、更正与离线AI记录</summary><p>当前回放：FY2024 → FY2025，跨报告期数据并存。来源是2025更正后年报，但未载入同年度原版进行字段比对，不能判定这项收入被更正。表内第37页与第185页存在0.01元差异，保留来源冲突。导入时间在确认入库后单独记录。</p><p>离线流程：披露材料 → 开发阶段Codex候选 → 原句及字段校验 → 操作者复核 → 关联判断待复核。此处不发生在线模型调用。</p><a href="deliverables/AI样例记录.json" target="_blank">查看候选与分析记录 ↗</a></details></section>`;}
function showResearchSample(id){const x=sampleById(id);if(!x)return;modal(`<div class="eyebrow">研究简报 · ${x.id}</div><h2>${esc(x.title)}</h2><span class="badge yellow">AI 分析样例 · 离线回放</span><div class="brief-summary">${esc(x.summary)}</div><section class="brief-section"><h3>披露事实</h3>${x.citations.map(id=>{const c=data.claims.find(c=>c.id===id);return `<div class="brief-fact"><p>${esc(c.text)}</p>${badge(c.grade)} <small>${esc(periodLabel(c))}</small> ${claimButton(c,'['+id+'] 证据')}</div>`}).join('')}</section><section class="brief-section"><h3>研究判断</h3><p>${esc(x.inference)}</p></section><section class="brief-section"><h3>待验证</h3>${x.gaps.map(t=>`<p class="brief-gap">${esc(t)}</p>`).join('')}</section><details class="inline-details"><summary>生成与验证记录</summary><p>开发阶段由 Codex 依据所列证据生成并经引用、等级与字段校验；尚待研究员复核。这里回放已保存样例，不发生在线模型调用。</p><a href="deliverables/AI使用与验证记录.md" target="_blank">查看记录 ↗</a></details><div class="modal-actions"><button id="sample-route">${x.route==='compare'?'公司对比':x.route==='updates'?'查看更新':'返回证据'}</button><button class="primary" id="sample-save">${notebook.some(r=>r.id===id)?'打开研究台账':'保存到研究台账'}</button></div>`);$('#modal').querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{$('#modal').close();showClaim(b.dataset.claim)});$('#sample-save').onclick=()=>{try{if(!notebook.some(r=>r.id===id))saveNotebook([...notebook,newResearchRecord(x,data)]);$('#modal').close();view='notebook';render();showNotebook(id)}catch(e){toast('保存失败：'+e.message)}};$('#sample-route').onclick=()=>{$('#modal').close();view=x.route;render();window.scrollTo(0,0)};}
function notebookView(){return `<div class="notebook-toolbar"><span class="small">本机研究记录 · ${notebook.length} 项</span><div class="btnrow"><button id="notebook-backup">备份</button><label class="file-action">恢复<input id="notebook-restore" type="file" accept=".json,application/json"></label></div></div>${notebook.length?`<div class="study-grid">${notebook.map(r=>{const changed=evidenceChanged(r,data);return `<article class="card study-card"><div class="study-meta"><span class="badge ${changed?'red':r.status==='跟踪中'?'yellow':'neutral'}">${changed?'相关事实变化 · 待复核':r.status}</span><small>v${r.version}</small></div><h2>${esc(r.title)}</h2><p>${esc(r.judgment)}</p><small>${esc(r.at.slice(0,10))} · ${r.snapshot.length} 条快照证据</small><div class="btnrow"><button class="primary" data-study="${r.id}">打开研究</button><button data-study-export="${r.id}">导出简报</button></div></article>`}).join('')}</div>`:'<div class="empty notebook-empty">暂无研究记录</div>'}<section class="card"><div class="card-head"><h2>研究样例</h2><span class="small">AI 分析 · 离线回放</span></div><div class="sample-grid">${RESEARCH_SAMPLES.map(x=>`<button data-research-sample="${x.id}"><strong>${x.short}</strong><span>${x.summary}</span><small>查看简报 ↗</small></button>`).join('')}</div></section>`;}
function showNotebook(id){const r=notebook.find(x=>x.id===id);if(!r)return;const changed=evidenceChanged(r,data),current=relatedClaims(r.citations,data,r.dependencies);modal(`<div class="eyebrow">研究台账 · v${r.version}</div><h2>${esc(r.title)}</h2><span class="badge ${changed?'red':'neutral'}">${changed?'相关事实变化，原判断待复核':r.status}</span>${changed?'<p class="review-change">仅相关事实版本、期间、口径或有效性变化触发提醒。待复核不等于原判断失效，可维持、修订或暂缓。</p>':''}<details class="inline-details" ${changed?'open':''}><summary>当前关联证据 · ${current.length} 条</summary>${current.map(c=>`<div class="brief-fact"><p>${esc(c.text)}</p>${badge(c.grade)} <small>${esc(periodLabel(c))}</small> ${claimButton(c,'['+c.id+'] 详情')}</div>`).join('')}</details><div class="journal-form"><label>研究判断<textarea id="study-judgment" maxlength="3000">${esc(r.judgment)}</textarea></label><label>跟踪指标 / 待验证<textarea id="study-watch" maxlength="3000">${esc(r.watch)}</textarea></label><label>关键假设（每行一条）<textarea id="study-assumptions" maxlength="6000">${esc(r.assumptions.map(a=>a.text).join('\n'))}</textarea></label><label>复核决定<select id="study-decision"><option>维持原判断</option><option>修订判断</option><option>暂缓判断</option></select></label><label>复核人 / 署名（自填）<input id="study-reviewer" maxlength="100"></label><label>复核理由<textarea id="study-reason" maxlength="1000"></textarea></label><label>研究状态<select id="study-status">${['待复核','跟踪中','已归档'].map(v=>`<option ${v===r.status?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="check"><input type="checkbox" id="study-confirm">已核对当前证据与研究判断</label><p id="study-error" class="small" role="alert"></p><div class="modal-actions"><button id="study-download">导出简报</button><button class="primary" id="study-revise" disabled>保存新版本</button></div><details class="inline-details"><summary>版本记录 · ${r.revisions.length+1} 版</summary><p>v${r.version} · ${esc(r.at)} · ${esc(r.status)}</p>${r.review?`<p>${r.review.decision} · ${esc(r.review.reviewer)}<br>${esc(r.review.reason)}</p>`:''}<p>绑定 ${r.dependencies.length} 个事实字段；${r.dependencies.some(d=>d.watchNextPeriod)?'含下一报告期跟踪':'固定报告期'}</p>${r.assumptions.map(a=>`<p>假设 ${esc(a.id)} v${a.version} · ${esc(a.text)}</p>`).join('')}${[...r.revisions].reverse().map(v=>`<p>v${v.version} · ${esc(v.at)}<br>${esc(v.judgment)}</p>`).join('')}<p>AI 样例经编辑后仍需研究员负责复核。最多保留最近 10 个历史版本。</p></details>`);$('#modal').querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{$('#modal').close();showClaim(b.dataset.claim)});$('#study-confirm').onchange=e=>$('#study-revise').disabled=!e.target.checked;for(const key of ['study-judgment','study-watch','study-status','study-decision','study-assumptions','study-reviewer','study-reason'])$('#'+key).oninput=()=>{$('#study-confirm').checked=false;$('#study-revise').disabled=true};$('#study-download').onclick=()=>{$('#modal').close();showStudyExport(r)};$('#study-revise').onclick=()=>{try{const next=reviseResearch(r,{judgment:$('#study-judgment').value,watch:$('#study-watch').value,status:$('#study-status').value,confirmed:$('#study-confirm').checked,decision:$('#study-decision').value,reviewer:$('#study-reviewer').value,assumptionsText:$('#study-assumptions').value,reason:$('#study-reason').value},data);saveNotebook(notebook.map(x=>x.id===id?next:x));$('#modal').close();render();toast('已保存 v'+next.version+'，旧版与证据快照保留')}catch(e){$('#study-error').textContent=e.message}};}
function showStudyExport(r){const content=researchMarkdown(r,data);modal(`<div class="eyebrow">研究交付 · Markdown</div><h2>${esc(r.title)}</h2><textarea class="export-preview" aria-label="研究简报 Markdown" readonly>${esc(content)}</textarea><div class="modal-actions"><button id="download-study-file" class="primary">下载 Markdown</button></div>`);$('#download-study-file').onclick=()=>{download('ChainLens-'+r.id+'.md',content,'text/markdown');toast('已生成简报文件')};}
function bindResearch(){document.querySelectorAll('[data-research-sample]').forEach(b=>b.onclick=()=>showResearchSample(b.dataset.researchSample));document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>showNotebook(b.dataset.study));document.querySelectorAll('[data-study-export]').forEach(b=>b.onclick=()=>showStudyExport(notebook.find(r=>r.id===b.dataset.studyExport)));if($('#load-official'))$('#load-official').onclick=()=>{try{draft=validateUpdate(OFFICIAL_UPDATE,data);updateText=JSON.stringify(draft,null,2);updateMode='form';updateError='';render()}catch(e){toast(e.message)}};if($('#notebook-backup'))$('#notebook-backup').onclick=()=>download('ChainLens-notebook.json',JSON.stringify({format:'chainlens-humanoid-notebook-v2',records:notebook},null,2));if($('#notebook-restore'))$('#notebook-restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('备份超过500KB');const x=JSON.parse(await f.text());if(x.format!=='chainlens-humanoid-notebook-v2')throw Error('备份类型不匹配');const incoming=validateNotebook(x.records),merged=[...notebook];for(const r of incoming){if(merged.some(a=>a.id===r.id))throw Error('存在同名研究；为防覆盖，请使用原台账或在其他浏览器恢复');merged.push(r)}saveNotebook(merged);render();toast('研究台账已恢复')}catch(e){toast('恢复失败：'+e.message)}};}

function calc(){if(!$('#calc-result'))return;const s=data.scenarios.find(x=>x.id===scenario),r=sensitivity(s.base,exposure,volume,price);$('#calc-result').innerHTML=`<span class="small">相对产品组基准的收入变化（${s.unit}）</span><strong>${r.delta>=0?'+':''}${(r.delta/1e6).toFixed(2)} <small>百万</small></strong><span class="small">该产品组收入变化 ${r.percent>=0?'+':''}${r.percent.toFixed(2)}% · 情景后 ${(r.total/1e6).toFixed(2)} 百万 ${s.unit}</span>`}
function render(){const focus=document.activeElement?.id,pos=document.activeElement?.selectionStart;$('#app').innerHTML=shell();bind();if(view==='scenario')calc();if(focus&&$('#'+focus)){try{$('#'+focus).focus();if(pos!=null)$('#'+focus).setSelectionRange(pos,pos)}catch{}}}
function modal(html){$('#modal').innerHTML=`<button class="close" aria-label="关闭弹窗">✕</button><div class="inner">${html}</div>`;$('#modal .close').onclick=()=>$('#modal').close();$('#modal').querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const id=b.dataset.source;$('#modal').close();showSource(id)});$('#modal').showModal()}
function showSource(id){if(id==='deliverables'){view='delivery';render();window.scrollTo(0,0);return}if(id==='method'){modal(`<div class="eyebrow">METHODOLOGY / v1.0</div><h2>分类与证据口径</h2><p>按“核心零部件 → 执行与控制 → 整机与应用”分层。分类反映功能，不代表每一种技术路线都适用于所有人形机器人。公司可跨节点，通用工业业务与人形应用分别核验。</p><p>这是本产品自建的研究分类，不是交易所、申万或 iFinD 正式行业标准。允许公司跨节点；箭头不代表采购关系。上游与下游目前保留结构，但未完整覆盖公司。</p><h3>首版覆盖清单</h3><div class="table-wrap"><table><thead><tr><th>节点</th><th>公司 / 关系</th><th>状态</th><th>来源</th></tr></thead><tbody>${coverageRows(data).map(r=>`<tr><td>${r.node}</td><td>${r.company}<br>${r.relation}</td><td>${r.status}</td><td>${r.source?srcButton(r.source):'—'}</td></tr>`).join('')}</tbody></table></div><p>按唯一关系计数；引文、结构入口与缺口分别列示。未核实的采购关系不计为供应商覆盖。</p><div class="taxonomy-list">${data.levels.map(l=>`<h3>${l.name}</h3>${l.nodes.map(n=>`<p><b>${n.name}</b><br>${NODE_CRITERIA[n.id]}</p>`).join('')}`).join('')}</div><p class="small">产品功能参考：${srcButton('GD24')} ${srcButton('HD25')} ${srcButton('TS25')}。具体数字以每条关系的原始来源和口径为准。</p>${Object.entries(GRADES).map(([g,v])=>`<p>${badge(g)} ${v.desc}</p>`).join('')}<p>等级是证据状态，不是统计概率，不是投资评级。图表保留披露项目原名，研究分类与披露分类分别展示；无法拆分时不自行拆分。数字保留各公司报告期与原币种；不将出货量视为收入，不将集团收入视为概念营收。</p>`);return}const s=data.sources.find(x=>x.id===id);if(!s)return;modal(`<div class="eyebrow">PRIMARY SOURCE / ${esc(id)}</div><h2>${esc(s.title)}</h2><p>${esc(s.publisher)} · 发布日期 ${esc(s.date)}</p><div class="notice">${stale(s.date)?'历史披露 · 非实时数据。':'请复核材料有效期和报告期。'} </div><p><b>定位</b><br>${esc(s.locator)}</p><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">打开官方原文 ↗</a>`)}
function showClaim(id){const c=activeClaim(id);if(!c)return;const s=data.sources.find(x=>x.id===c.source),co=data.companies.find(x=>x.id===c.company),level=data.levels.find(l=>l.nodes.some(n=>n.id===c.node)),node=level.nodes.find(n=>n.id===c.node),target=scenarioForClaim(c);const rationale=c.grade==='E'?'这是一条与该环节相关的证据缺口记录，不代表公司已经属于该环节。':c.grade==='D'?'材料只支持技术应用或表述关联，不能据此认定该概念已有独立收入。':'原始材料披露或介绍了本条业务 / 产品，因此放入对应功能环节；收入、交付和产品介绍仍按各自等级区分。';modal(`<div class="eyebrow">业务证据 / ${esc(c.id)}</div><h2>${co.name} · ${esc(c.concept)}</h2>${badge(c.grade)} <span class="badge neutral">${esc(periodLabel(c))}</span><p><b>研究分类：</b>${level.name} → ${node.name}<br><b>披露分类：</b>${esc(c.disclosedName||'未披露 / 不适用')}</p>${reviewMeta(c)}${['D','E'].includes(c.grade)?`<p>${rationale}</p>`:''}<p><b>证据结论</b><br>${esc(c.text)}</p>${c.quote?`<blockquote>${esc(c.quote)}</blockquote><p class="small">原文短摘录 · ${esc(c.quoteNote)}</p>`:''}<p><b>使用边界</b><br>${esc(c.boundary)}</p>${c.gapCheck?`<div class="info-box">核查截至 ${c.gapCheck.checkedAt}<br>材料：${c.gapCheck.sourceIds.join('、')}<br>范围：${esc(c.gapCheck.range)}<br>缺项：${c.gapCheck.missing.join('、')} · ${c.missingReason}<br>非穷尽检索，不代表业务不存在。</div>`:''}<p><b>原文定位</b><br>${esc(c.locator)}</p><p class="small">${esc(s.title)}<br>${esc(s.publisher)} · 披露 ${esc(s.date)}${c.reviewed?' · 用户复核':''}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">官方原文 ↗</a><div class="claim-next"><div class="btnrow"><button id="claim-compare">公司对比</button>${target?'<button id="claim-scenario" class="primary">变化影响分析</button>':'<span class="small">'+(['D','E'].includes(c.grade)?'证据不足，暂不推演财务影响。':'当前没有直接对应的传导样例。')+'</span>'}</div></div>`);$('#claim-compare').onclick=()=>{$('#modal').close();pair=[c.company,c.company==='green'?'hds':'green'];view='compare';render();window.scrollTo(0,0)};if(target)$('#claim-scenario').onclick=()=>{$('#modal').close();scenario=target;contextClaim=c.id;view='scenario';render();window.scrollTo(0,0)}}

function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportReport(){if(view==='chain'){download('ChainLens-industry-chain.md',chainExport(data,selected||'reducer'),'text/markdown');return}if(view==='compare'){download('ChainLens-company-comparison.md',comparisonExport(ifind,pair),'text/markdown');return}if(['explore','library','funds','ai'].includes(view)){exportExplore();return}if(view==='hotspot'){exportHotspot();return}if(view==='notebook'){download('ChainLens-research-notebook.md',notebook.map(r=>researchMarkdown(r,data)).join('\n\n---\n\n'),'text/markdown');return}const claims=selectClaims(data,{q:view==='chain'?query:'',node:view==='chain'?selected:'',grade:view==='chain'?grade:'',market:view==='chain'?market:''});let t=`# 链证研究包\n\n导出时间：${new Date().toISOString()}\n数据期间：各公司分别标注；非实时研究。\n分类：核心零部件 → 执行与控制 → 整机与应用。\n等级是证据状态，不是概率或评级。\n\n`;for(const c of claims){const co=data.companies.find(x=>x.id===c.company),s=data.sources.find(x=>x.id===c.source);t+=`## [${c.id}] ${co.name} / ${c.concept}\n\n${c.grade} ${GRADES[c.grade].label} · ${c.period}\n\n${c.text}\n\n原句：${c.quote||'缺口记录，无肯定原句'}\n\n边界：${c.boundary}\n\n[${s.title}](${s.url})\n\n发布：${s.date}；定位：${c.locator}\n\n`}if(view==='compare'){const a=data.companies.find(x=>x.id===pair[0]),b=data.companies.find(x=>x.id===pair[1]);t+=`## 可比性研究判断：${a.name} / ${b.name}\n\n`+compareRows(a,b).map(r=>r.join('：')).join('\n\n')+'\n\n'}if(view==='scenario'){const s=data.scenarios.find(x=>x.id===scenario);t+=`## 条件性传导：${s.name}\n\n${s.steps.join(' → ')}\n\n反向条件：${s.counter}\n\n${s.id==='ramp'?`基准：${s.base} ${s.unit}；暴露 ${exposure}%；销量变化 ${volume}%；价格变化 ${price}%。\nΔ收入=${sensitivity(s.base,exposure,volume,price).delta} ${s.unit}。公式：R×E×[(1+V)×(1+P)-1]。`:'缺少政策资格、BOM、良率或合同数据；当前不量化影响金额。'}\n\n${s.boundary}\n\n`}t+='## 边界\n\n不构成投资建议。无实时行情或估值。扶摇未接入；iFinD已导入财务和公告快照。没有证据不等于没有业务。\n';download('ChainLens-research.md',t,'text/markdown');toast('已导出含来源、报告期与边界的研究包')}
async function ask(q){chatQuestion=q.trim();if(!chatQuestion){toast('请先输入研究问题');return}const model=$('#use-model')?.checked;answer={...retrieve(chatQuestion,data),mode:'rules'};if(!answer.refused&&/财务|营收|收入|利润|现金流/.test(chatQuestion))answer.ifindCompanies=matchCompanies(chatQuestion).map(c=>c.id).filter(id=>annualRows(ifind,id).length);if(/可比|比较/.test(q)&&answer.claims.length){answer.text+=' 比较需先限定重合业务，再检查产品架构、应用场景和会计口径；完整矩阵见「中外公司对比」。'}if(!model||answer.refused||!answer.claims.length){render();return}busy=true;render();try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);let r;try{r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,evidence:answer.claims}),signal:controller.signal})}finally{clearTimeout(timer)}if(!r.ok)throw Error('模型服务暂不可用（'+r.status+'）');const result=await r.json();if(typeof result.text!=='string'||!Array.isArray(result.citations)||!result.citations.length||result.citations.some(id=>!answer.claims.some(c=>c.id===id)))throw Error('模型返回无有效引用');answer.modelText=result.text;answer.mode='AI';}catch(e){answer.text+=' 在线模型未成功完成或未通过引用校验，已保留证据检索结果。';toast(e.name==='AbortError'?'模型请求超时，已降级为证据模式':e.message)}finally{busy=false;render()}}
function bind(){bindVisuals();bindIfind();bindExplore();bindResearch();bindHotspot();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;if(view==='scenario')contextClaim=null;render();window.scrollTo(0,0)});document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>showSource(b.dataset.source));document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>showClaim(b.dataset.claim));document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>ask(b.dataset.ask));$('#export').onclick=exportReport;document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{view='chain';selected='reducer';grade=market=query='';render();window.scrollTo(0,0)});document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>document.querySelector(b.dataset.jump==='map'?'#chain-map':'#company-evidence')?.scrollIntoView({behavior:'smooth',block:'start'}));$('#global-search-form').onsubmit=e=>{e.preventDefault();query=$('#global-search').value.trim();companyQuery=query;companyNode=companyMarket=companyDepth='';view='explore';render();window.scrollTo(0,0);};
 if($('#question')){$('#question').oninput=e=>chatQuestion=e.target.value;$('#ask').onclick=()=>ask($('#question').value)}
 if(view==='chain'){
 document.querySelectorAll('[data-chain-node]').forEach(b=>b.onclick=()=>{selected=b.dataset.chainNode;chainExpanded=null;chainFilter='all';chainTab='structure';render();document.querySelector('#chain-detail')?.scrollIntoView({behavior:'smooth',block:'start'})});
 document.querySelectorAll('[data-chain-tab]').forEach(b=>b.onclick=()=>{chainTab=b.dataset.chainTab;render()});
 document.querySelectorAll('[data-chain-expand]').forEach(b=>b.onclick=()=>{chainExpanded=chainExpanded===b.dataset.chainExpand?null:b.dataset.chainExpand;render()});
 document.querySelectorAll('[data-chain-source]').forEach(b=>b.onclick=()=>modal(chainSourceDetails(b.dataset.chainSource)));
 document.querySelectorAll('[data-chain-retrieval]').forEach(b=>b.onclick=()=>modal(chainRetrievalDetails(b.dataset.chainRetrieval)));
 document.querySelectorAll('[data-chain-compare]').forEach(b=>b.onclick=()=>{pair=b.dataset.chainCompare.split(',');view='compare';compareQuarter=compareExpanded=null;render();window.scrollTo(0,0)});
 document.querySelectorAll('[data-chain-ai]').forEach(b=>b.onclick=()=>{const c=companyById(b.dataset.chainAi);chatQuestion=c.name+'与人形机器人有哪些真实业务关系？';view='ai';answer=null;render();window.scrollTo(0,0);ask(chatQuestion)});
 $('#chain-evidence-filter').onchange=e=>{chainFilter=e.target.value;chainExpanded=null;render()};
 }
 if(view==='compare')for(const [id,index]of [['pair-a',0],['pair-b',1]])$('#'+id).onchange=e=>{compareQuarter=null;compareExpanded=null;pair[index]=e.target.value;if(pair[0]===pair[1])pair[1-index]=CATALOG.find(c=>c.id!==pair[index]).id;render()};
 if(view==='scenario'){document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;contextClaim=null;render()});for(const id of ['exposure','volume','price'])if($('#'+id))$('#'+id).oninput=e=>{const v=Number(e.target.value);if(id==='exposure'){exposure=v;const grid=document.querySelector('.impact-grid');if(grid){grid.outerHTML=impactGrid(data.scenarios.find(s=>s.id===scenario),exposure);bindVisuals()}}if(id==='volume')volume=v;if(id==='price')price=v;$('#'+id+'-value').textContent=v+'%';calc()}}
 if(view==='updates'){$('#mode-form').onclick=()=>{if(updateMode==='json'){updateText=$('#update-json').value;try{JSON.parse(updateText||'{}')}catch{updateError='JSON 格式不完整，请先修正或重新载入示例。';render();return}}updateMode='form';draft=null;render()};$('#mode-json').onclick=()=>{if(updateMode==='form')updateText=JSON.stringify(collectEvidenceForm(),null,2);updateMode='json';draft=null;render()};document.querySelectorAll('[data-evidence-field]').forEach(el=>el.oninput=()=>{updateText=JSON.stringify(collectEvidenceForm(),null,2);draft=null;$('#approve')?.setAttribute('disabled','');if($('#review'))$('#review').disabled=true});$('#update-json').oninput=e=>{updateText=e.target.value;draft=null;$('#approve')?.setAttribute('disabled','');};$('#sample').onclick=()=>{updateText=JSON.stringify(importSample(),null,2);draft=null;updateError='';render()};$('#validate').onclick=()=>{try{updateText=updateMode==='form'?JSON.stringify(collectEvidenceForm(),null,2):$('#update-json').value;if(updateText.length>50000)throw Error('单条数据不得超过 50KB');draft=validateUpdate(JSON.parse(updateText),data);updateError=''}catch(e){draft=null;updateError=readableUpdateError(e.message)}render()};$('#upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>50000){updateError='文件超过 50KB';render();return}updateText=await f.text();updateMode='json';draft=null;updateError='';render()};if($('#review'))$('#review').onchange=e=>$('#approve').disabled=!e.target.checked;if($('#approve'))$('#approve').onclick=async()=>{if(!$('#review').checked)return;try{const claim=validateUpdate(draft,data),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(claim))))).map(x=>x.toString(16).padStart(2,'0')).join('');const reviewer=$('#evidence-reviewer').value.trim(),reason=$('#evidence-reason').value.trim();if(!reviewer||!reason)throw Error('请填写复核人和理由');saveHistory([...history,{eventId:'ADD_'+Date.now(),type:'add',claim,at:new Date().toISOString(),hash,reviewer,reason}]);draft=null;updateText='';updateError='';render();toast('已写入本机证据版本；产业链与助手已同步')}catch(e){updateError='保存失败：'+e.message;render()}};$('#rollback').onclick=showRestore;$('#export-history').onclick=()=>download('ChainLens-update-backup.json',JSON.stringify({format:'chainlens-humanoid-history-v2',history},null,2));$('#restore-history').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('备份超过 500KB');const x=JSON.parse(await f.text());if(x.format!=='chainlens-humanoid-history-v2'||!Array.isArray(x.history)||x.history.length>100)throw Error('备份格式无效');const next=validateHistory(x.history,base);for(const h of next.filter(e=>e.type==='add')){const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(h.claim))))).map(z=>z.toString(16).padStart(2,'0')).join('');if(hash!==h.hash)throw Error('备份摘要不一致')}saveHistory(next);render();toast('已恢复经过校验的更新记录')}catch(e){toast('恢复失败：'+e.message)}}}}

function showIfindStatus(){modal(providerDetails(ifind,ifindError));bindIfind();}
async function reloadIfind(){const result=await loadSnapshot(fetch,ifind);ifind=result.snapshot;ifindError=result.error;$('#modal').close();render();toast(result.error?'快照重载失败；已保留现有数据':'已重载本地iFinD快照；未发起新MCP查询');}
function bindIfind(){
 document.querySelectorAll('[data-ifind-status]').forEach(b=>b.onclick=showIfindStatus);
 document.querySelectorAll('[data-ifind-row]').forEach(b=>b.onclick=()=>{modal(rowDetails(ifind,b.dataset.ifindRow));bindModalLinks()});
 document.querySelectorAll('[data-ifind-notice]').forEach(b=>b.onclick=()=>{modal(noticeDetails(ifind,b.dataset.ifindNotice));bindModalLinks()});
 document.querySelectorAll('[data-ifind-company-notices]').forEach(b=>b.onclick=()=>{documentCompany=b.dataset.ifindCompanyNotices;documentQuery=documentKind='';view='library';render();window.scrollTo(0,0)});
 if($('#ifind-reload'))$('#ifind-reload').onclick=reloadIfind;
 document.querySelectorAll('[data-compare-preset]').forEach(b=>b.onclick=()=>{pair=b.dataset.comparePreset.split(',');compareQuarter=compareExpanded=null;render()});
 document.querySelectorAll('[data-compare-company]').forEach(b=>b.onclick=()=>{const id=b.dataset.compareCompany;pair=pair[0]===id?[id,CATALOG.find(c=>c.id!==id).id]:[pair[0],id];compareQuarter=compareExpanded=null;render()});
 document.querySelectorAll('[data-compare-scope]').forEach(b=>b.onclick=()=>{compareScope=b.dataset.compareScope;render()});
 document.querySelectorAll('[data-compare-metric]').forEach(b=>b.onclick=()=>{compareMetric=b.dataset.compareMetric;render()});
 document.querySelectorAll('[data-expand-finance]').forEach(b=>b.onclick=()=>{compareExpanded=compareExpanded===b.dataset.expandFinance?null:b.dataset.expandFinance;render()});
 document.querySelectorAll('[data-close-quarter]').forEach(b=>b.onclick=()=>{compareQuarter=null;render()});
 const tooltip=$('#compare-tooltip');
 document.querySelectorAll('[data-compare-quarter]').forEach(b=>{const index=Number(b.dataset.compareQuarter),show=()=>{if(!tooltip)return;tooltip.innerHTML=quarterTooltip(ifind,pair,compareMetric,index);tooltip.hidden=false;tooltip.style.left=index>1?'auto':'8%';tooltip.style.right=index>1?'5%':'auto';};b.onmouseenter=show;b.onfocus=show;b.onmouseleave=()=>{if(tooltip)tooltip.hidden=true};b.onblur=()=>{if(tooltip)tooltip.hidden=true};b.onclick=()=>{compareQuarter=index;render();document.querySelector('.compare-quarter-detail')?.scrollIntoView({behavior:'smooth',block:'nearest'})};});
}

async function init(){try{const r=await fetch('./data.json?v=humanoid-20',{cache:'no-store'});if(!r.ok)throw Error('数据请求失败 '+r.status);base=await r.json();if(base.version!=='humanoid.2'||!base.companies.some(c=>c.id==='green')||base.companies.some(c=>['sg','en','se'].includes(c.id)))throw Error('研究数据版本不匹配，请重新加载');try{const raw=JSON.parse(localStorage.getItem('chainlens-humanoid-history-v2')||'[]');if(!Array.isArray(raw)||raw.length>100)throw Error();history=validateHistory(raw,base)}catch{history=[];toast('本地更新记录不可读，已载入原始快照')}rebuild();const provider=await loadSnapshot();ifind=provider.snapshot;ifindError=provider.error;try{const ids=JSON.parse(localStorage.getItem('chainlens-company-watch-v1')||'[]');watchCompanies=Array.isArray(ids)?[...new Set(ids.filter(id=>CATALOG.some(c=>c.id===id)))]:[]}catch{watchCompanies=[]}try{notebook=validateNotebook(JSON.parse(localStorage.getItem('chainlens-humanoid-notebook-v2')||'[]'))}catch{notebook=[];toast('研究台账读取失败；原始存储未覆盖')}const target=new URLSearchParams(location.search).get('view');if(target==='chain'){view='chain';selected=new URLSearchParams(location.search).get('node')||'reducer'}render();try{const status=await fetch('/api/status');if(status.ok){const x=await status.json();online=x.ai===true;if(online)render()}}catch{}}catch(e){$('#app').innerHTML=`<main style="padding:50px;max-width:700px"><h1>研究数据暂时不可用</h1><p style="margin:20px 0">${esc(e.message)}。不会用虚构数字填充页面。</p><button id="retry">重新加载</button></main>`;$('#retry').onclick=()=>location.reload()}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});init();

function bindVisuals(){bindVisualTips();document.querySelectorAll('[data-viz-relation]').forEach(b=>b.onclick=()=>{const [id,node]=b.dataset.vizRelation.split(',');selected=node;chainExpanded=id+':'+node;chainTab='structure';view='chain';render();document.querySelector('#company-evidence')?.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelectorAll('[data-viz-metric]').forEach(b=>b.onclick=()=>{modal(metricDetails(ifind,b.dataset.vizMetric));bindModalLinks()});document.querySelectorAll('[data-viz-sensitivity]').forEach(b=>b.onclick=()=>{[volume,price]=b.dataset.vizSensitivity.split(',').map(Number);render();calc()});}
